insert into private.study_guides (guide, chunks, sha256) values ('study_guide_lag_acs213', 45, 'c415613960c22b0bc09adaa1bf52625885507c4763a4b3411f25c3b339272de2');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 1, $study_guide${"guide":"study_guide_lag_acs213","code":"LAG-ACS213","courseId":"e6ebc3e3-e990-5459-84af-06a4f05aea89","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"7de7ab8f-ff10-5502-845a-0680e91142e1","create":true,"after":{"title":"Mathematics for Business","body":"Every topic is examinable. Work through every worked example with a calculator.","outcomes":["Integrate functions and use integration to find totals from marginal functions, areas, and consumer's and producer's surplus.","Use algebraic, exponential and logarithmic functions to model and solve business and economics problems.","Differentiate functions and interpret marginal cost, revenue, profit and elasticity.","Find maximum and minimum values, including with two variables and constraints, and use growth and decay models.","Find market equilibrium and break-even points and analyse cost, revenue and profit.","Calculate simple and compound interest, present values, annuities and loan repayments.","Work with matrices, determinants and inverses, and solve systems of equations.","Use arithmetic and geometric progressions in business problems.","Apply set operations and Venn diagrams to counting problems.","Model consumption, saving and market penetration."],"assessment":["Expect objective questions, mostly short calculations, plus some definitions and rules."]}},"retire":[],"notes":[{"kind":"note","itemId":"cb53b246-bf8b-5a51-b53b-7b61c099d079","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Integral Calculus Applications","body":"Integration as the reverse of differentiation and its basic rules; substitution; integration by parts; partial fractions; definite integrals and areas; total cost, revenue, profit and demand from marginal functions; consumer's and producer's surplus; total sales, income streams and continuous annuities.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"Integration as the reverse of differentiation and its basic rules; substitution; integration by parts; partial fractions; definite integrals and areas; total cost, revenue, profit and demand from marginal functions; consumer's and producer's surplus; total sales, income streams and continuous annuities."}],"lessons":[{"number":"1.1","title":"Integration as anti-differentiation: the basic rules","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Integral (anti-derivative):","bold":true},{"text":" if d/dx F(x) = f(x), then F(x) is an integral of f(x), written F(x) = ∫ f(x) dx. f(x) is the "},{"text":"integrand","bold":true},{"text":"; finding F is "},{"text":"integration","bold":true},{"text":". Integration is the reverse process of differentiation."}]},{"text":[{"text":"Indefinite integral:","bold":true},{"text":" ∫ f(x) dx = F(x) + c. The "},{"text":"constant of integration c","bold":true},{"text":" appears because the derivative of any constant is 0 (x^3, x^3 + 2 and x^3 + c all differentiate to 3x^2)."}]},{"text":[{"text":"Two properties (direct integration):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"∫ k·f(x) dx = k·∫ f(x) dx (a constant factor comes outside)."}]},{"text":[{"text":"∫ [f(x) ± g(x)] dx = ∫ f(x) dx ± ∫ g(x) dx (integrate term by term)."}]}]}]}]},{"type":"table","header":[[{"text":"Integrand"}],[{"text":"Integral (add + c)"}]],"rows":[[[{"text":"k (constant)"}],[{"text":"kx"}]],[[{"text":"x^n (n ≠ −1)"}],[{"text":"x^(n+1)/(n + 1)"}]],[[{"text":"1/x = x^(−1)"}],[{"text":"ln x (x > 0)"}]],[[{"text":"e^x"}],[{"text":"e^x"}]],[[{"text":"e^(mx)"}],[{"text":"e^(mx)/m"}]],[[{"text":"a^x (a > 0, a ≠ 1)"}],[{"text":"a^x/ln a"}]],[[{"text":"a^(mx)"}],[{"text":"a^(mx)/(m·ln a)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Power rule in words:","bold":true},{"text":" add 1 to the power, then divide by the new power. It fails only for n = −1, which gives ln x."}]},{"text":[{"text":"Check any answer","bold":true},{"text":" by differentiating it."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Rewrite roots and fractions as powers first: sqrt(x) = x^(1/2), 1/x^3 = x^(−3), 1/sqrt(x) = x^(−1/2)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"∫ 10x^5 dx = 10·x^6/6 + c = (5/3)x^6 + c. (Trap: 2x^6 forgets to divide properly; 50x^4 is the derivative.)"}]},{"text":[{"text":"∫ (x^5 + 3x^2 − 5x) dx = (1/6)x^6 + x^3 − (5/2)x^2 + c."}]},{"text":[{"text":"∫ x^10 dx = x^11/11 + c; ∫ x^(1/2) dx = x^(3/2)/(3/2) = (2/3)x^(3/2) + c."}]},{"text":[{"text":"∫ 1/x^3 dx = ∫ x^(−3) dx = x^(−2)/(−2) = −1/(2x^2) + c."}]},{"text":[{"text":"∫ (3x^(−1) + 4x^2 − 3x + 8) dx = 3 ln x + (4/3)x^3 − (3/2)x^2 + 8x + c."}]},{"text":[{"text":"∫ (2 sqrt(x) + 5x^(−1) + 3x^2) dx = 2·(2/3)x^(3/2) + 5 ln x + x^3 = (4/3)x^(3/2) + 5 ln x + x^3 + c."}]},{"text":[{"text":"∫ (1/x^2 − 1/x^3) dx = −1/x + 1/(2x^2) + c; ∫ (sqrt(x) + x^(1/3)) dx = (2/3)x^(3/2) + (3/4)x^(4/3) + c."}]},{"text":[{"text":"∫ (sqrt(x) − x/2 + 2/sqrt(x)) dx = (2/3)x^(3/2) − x^2/4 + 4 sqrt(x) + c."}]}]},{"type":"paragraph","text":[{"text":"Products and quotients: expand or divide first.","bold":true},{"text":" Never integrate each bracket separately."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"∫ (1 + x)(1 − 3x) dx = ∫ (1 − 2x − 3x^2) dx = x − x^2 − x^3 + c."}]},{"text":[{"text":"∫ (1 + x)(1 + 2x) dx = ∫ (1 + 3x + 2x^2) dx = x + 3x^2/2 + 2x^3/3 + c."}]},{"text":[{"text":"∫ (x^2 − 1)^2 dx = ∫ (x^4 − 2x^2 + 1) dx = x^5/5 − 2x^3/3 + x + c."}]},{"text":[{"text":"∫ (x + sqrt(x))^2 dx = ∫ (x^2 + 2x^(3/2) + x) dx = x^3/3 + 4x^(5/2)/5 + x^2/2 + c."}]},{"text":[{"text":"∫ (x − 1/x)^3 dx = ∫ (x^3 − 3x + 3/x − x^(−3)) dx = x^4/4 − 3x^2/2 + 3 ln x + 1/(2x^2) + c."}]},{"text":[{"text":"∫ (x^4 + 1)/x^2 dx = ∫ (x^2 + x^(−2)) dx = x^3/3 − 1/x + c."}]},{"text":[{"text":"∫ (x^2 + 1)x dx = ∫ (x^3 + x) dx = x^4/4 + x^2/2 + c, which equals (1/4)(x^2 + 1)^2 + c (they differ only by the constant 1/4)."}]}]},{"type":"paragraph","text":[{"text":"Exponentials and constants.","bold":true}]},{"type":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 2, $study_guide$list","ordered":false,"items":[{"text":[{"text":"∫ (3x^2 + e^x + a^x) dx = x^3 + e^x + a^x/ln a + c. (Trap: a^x·ln a is the derivative, not the integral.)"}]},{"text":[{"text":"∫ (3x^5 + e^((n+1)x) + a^(5x)) dx = x^6/2 + e^((n+1)x)/(n + 1) + a^(5x)/(5 ln a) + c."}]},{"text":[{"text":"∫ (2^x + (1/2)e^(−x) + 4/x − x^(−1/3)) dx = 2^x/ln 2 − (1/2)e^(−x) + 4 ln x − (3/2)x^(2/3) + c."}]},{"text":[{"text":"∫ (x^(1/3) + e^3) dx = (3/4)x^(4/3) + e^3·x + c. e^3 is a number, so it integrates like any constant k."}]}]}]},{"number":"1.2","title":"Integration by substitution","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Method:","bold":true},{"text":" choose u = the \"inner\" expression; find du = u'(x) dx; rewrite the whole integral in u; integrate; put x back."}]},{"text":[{"text":"Linear inside (ax + b), a ≠ 0:","bold":true},{"text":" integrate as usual, then divide by a."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"∫ (ax + b)^n dx = (ax + b)^(n+1)/[a(n + 1)] + c, n ≠ −1."}]},{"text":[{"text":"∫ 1/(ax + b) dx = (1/a) ln(ax + b) + c."}]},{"text":[{"text":"∫ e^(ax + b) dx = (1/a) e^(ax + b) + c."}]}]}]},{"text":[{"text":"Log pattern:","bold":true},{"text":" ∫ f'(x)/f(x) dx = ln f(x) + c (top is the derivative of the bottom)."}]},{"text":[{"text":"Power pattern:","bold":true},{"text":" ∫ f'(x)·[f(x)]^n dx = [f(x)]^(n+1)/(n + 1) + c, n ≠ −1."}]},{"text":[{"text":"If the top is only a "},{"text":"constant multiple","bold":true},{"text":" of f'(x), adjust by that constant."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Linear inside.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"∫ (2x + 3)^5 dx: u = 2x + 3, du = 2 dx, so (1/2)∫ u^5 du = u^6/12 = (1/12)(2x + 3)^6 + c."}]},{"text":[{"text":"∫ dx/(5x − 6)^3: u = 5x − 6, du = 5 dx: (1/5)∫ u^(−3) du = (1/5)·u^(−2)/(−2) = −1/(10(5x − 6)^2) + c."}]},{"text":[{"text":"∫ dw/(7 − 2w)^3: u = 7 − 2w, du = −2 dw: (−1/2)·u^(−2)/(−2) = +1/(4(7 − 2w)^2) + c. (The negative a turns the sign positive; watch this.)"}]},{"text":[{"text":"∫ (5 − 2x)^(−3/2) dx: (−1/2)·u^(−1/2)/(−1/2) = u^(−1/2) = 1/sqrt(5 − 2x) + c."}]},{"text":[{"text":"∫ dx/(1 − 4x) = −(1/4) ln(1 − 4x) + c; ∫ e^(2x − 1) dx = (1/2)e^(2x − 1) + c."}]}]},{"type":"paragraph","text":[{"text":"Log pattern.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"∫ (3x^2 + 2)/(x^3 + 2x + 5) dx = ln(x^3 + 2x + 5) + c, since the top is exactly the derivative of the bottom."}]},{"text":[{"text":"∫ (4x^3 + 2x)/(x^4 + x^2 + 2) dx = ln(x^4 + x^2 + 2) + c."}]},{"text":[{"text":"∫ x/(2x^2 + 3) dx: derivative of the bottom is 4x, so = (1/4) ln(2x^2 + 3) + c."}]},{"text":[{"text":"∫ 1/(e^x + 1) dx: multiply top and bottom by e^(−x) to get ∫ e^(−x)/(1 + e^(−x)) dx. The derivative of 1 + e^(−x) is −e^(−x), so the answer is −ln(1 + e^(−x)) + c."}]}]},{"type":"paragraph","text":[{"text":"Power pattern.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"∫ x^2(2x^3 + 3)^5 dx: u = 2x^3 + 3, du = 6x^2 dx: (1/6)∫ u^5 du = (1/36)(2x^3 + 3)^6 + c."}]},{"text":[{"text":"∫ x/sqrt(1 + x^2) dx: u = 1 + x^2, du = 2x dx: (1/2)∫ u^(−1/2) du = u^(1/2) = sqrt(1 + x^2) + c."}]},{"text":[{"text":"∫ 8x^2/(x^3 + 2)^3 dx: u = x^3 + 2, du = 3x^2 dx: (8/3)∫ u^(−3) du = (8/3)(−1/(2u^2)) = −4/(3(x^3 + 2)^2) + c."}]},{"text":[{"text":"∫ (ax^2 + 2bx + 2c)^5 (ax + b) dx: du = (2ax + 2b) dx = 2(ax + b) dx, so (1/2)·u^6/6 = (ax^2 + 2bx + 2c)^6/12 + K."}]},{"text":[{"text":"∫ (1/x) ln x dx: u = ln x, du = dx/x: ∫ u du = (1/2)(ln x)^2 + c."}]},{"text":[{"text":"∫ 1/(x(1 + ln x)^3) dx: u = 1 + ln x: ∫ u^(−3) du = −1/(2(1 + ln x)^2) + c."}]},{"text":[{"text":"∫ e^(sqrt(x + 1))/sqrt(x + 1) dx: u = sqrt(x + 1), du = dx/(2 sqrt(x + 1)): 2∫ e^u du = 2e^(sqrt(x + 1)) + c."}]}]},{"type":"paragraph","text":[{"text":"Substitution can leave ∫ ln u du (Lesson 1.3): ∫ (1/x) ln(ln x) dx = (ln x)[ln(ln x) − 1] + c, and ∫ 2x ln(a + x^2) dx = (a + x^2)[ln(a + x^2) − 1] + c."}]}]},{"number":"1.3","title":"Integration by parts and partial fractions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Integration by parts:","bold":true},{"text":" ∫ u dv = uv − ∫ v du (equivalently ∫ u·v' dx = u·v − ∫ v·u' dx)."}]},{"text":[{"text":"Choosing u:","bold":true},{"text":" take u = ln x whenever ln x appears; otherwise take u = the power of x (x, x^2) and dv = the exponential."}]},{"text":[{"text":"Standard results:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"∫ ln x dx = x ln x − x + c"}]},{"text":[{"text":"∫ x e^x dx = e^x(x − 1) + c"}]},{"text":[{"text":"∫ x e^(−x) dx = −e^(−x)(x + 1) + c"}]},{"text":[{"text":"∫ x^n ln x dx = [x^(n+1)/(n + 1)] ln x − x^(n+1)/(n + 1)^2 + c, n ≠ −1"}]},{"text":[{"text":"∫ x^2 e^(kx) dx = e^(kx)[x^2/k − 2x/k^2 + 2/k^3] + c (parts used twice)"}]}]}]},{"text":[{"text":"Partial fractions","bold":true},{"text":" (use when substitution fails on a fraction):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"If the degree of the top ≥ the degree of the bottom, "},{"text":"divide first","bold":true},{"text":" (this produces the extra \"x\" term)."}]},{"text":[{"text":"Split: (px + q)/((x − α)(x − β)) = A/(x − α) + B/(x − β)."}]},{"text":[{"text":"Find A and B by putting x = α, then x = β (cover-up)."}]},{"text":[{"text":"Integrate each part with ∫ 1/(ax + b) dx = (1/a) ln(ax + b)."}]}]}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"By parts, step by step.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"∫ x e^x dx: u = x, dv = e^x dx, so du = dx, v = e^x. Then x e^x − ∫ e^x dx = x e^x − e^x = e^x(x − 1) + c."}]},{"text":[{"text":"∫ ln x dx: u = ln x, dv = dx, du = dx/x, v = x. Then x ln x − ∫ 1 dx = x ln x − x + c."}]},{"text":[{"text":"∫ x ln x dx: u = ln x, v = x^2/2: (x^2/2) ln x − ∫ (x/2) dx = (1/2)x^2 ln x − (1/4)x^2 + c."}]},{"text":[{"text":"∫ x^2 ln x dx: u = ln x, v = x^3/3: (x^3/3) ln$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 3, $study_guide$ x − ∫ x^2/3 dx = (x^3/3) ln x − x^3/9 = (x^3/9)(3 ln x − 1) + c."}]},{"text":[{"text":"∫ x e^(−x) dx: u = x, v = −e^(−x): −x e^(−x) + ∫ e^(−x) dx = −x e^(−x) − e^(−x) = −e^(−x)(x + 1) + c."}]},{"text":[{"text":"Using result 5: ∫ x^2 e^x dx = e^x(x^2 − 2x + 2) + c (k = 1); ∫ x^2 e^(2x) dx = e^(2x)[x^2/2 − x/2 + 1/4] = (1/2)e^(2x)(x^2 − x + 1/2) + c (k = 2); ∫ x^2 e^(3x) dx = x^2e^(3x)/3 − 2xe^(3x)/9 + 2e^(3x)/27 + c (k = 3). The signs alternate +, −, +."}]}]},{"type":"paragraph","text":[{"text":"Partial fractions.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"∫ (3x + 2)/((1 + x)(1 + 2x)) dx. Write 3x + 2 = A(1 + 2x) + B(1 + x). x = −1: −1 = −A, so A = 1. x = −1/2: 1/2 = B/2, so B = 1. Answer: ln(1 + x) + (1/2) ln(1 + 2x) + c."}]},{"text":[{"text":"∫ 1/((x + 1)(x + 3)) dx: A = 1/2, B = −1/2, giving (1/2)[ln(x + 1) − ln(x + 3)] + c."}]},{"text":[{"text":"∫ (x + 2)/(x^2 − 13x + 42) dx: factor x^2 − 13x + 42 = (x − 7)(x − 6). x = 7: A = 9/1 = 9. x = 6: B = 8/(−1) = −8. Answer: 9 ln(x − 7) − 8 ln(x − 6) + c."}]},{"text":[{"text":"∫ x/((x − 1)(2x + 1)) dx: A = 1/3, B = (−1/2)/(−3/2) = 1/3. Answer: (1/3) ln(x − 1) + (1/6) ln(2x + 1) = (1/6)[2 ln(x − 1) + ln(2x + 1)] + c."}]},{"text":[{"text":"∫ 1/(x − x^3) dx: x − x^3 = x(1 − x)(1 + x); A/x + B/(1 − x) + C/(1 + x) gives A = 1, B = 1/2, C = −1/2. Integral = ln x − (1/2) ln(1 − x) − (1/2) ln(1 + x) = (1/2) ln(x^2/(1 − x^2)) + c."}]},{"text":[{"text":"Improper fractions: x^2/((x − a)(x − b)) = 1 + A/(x − a) + B/(x − b), A = a^2/(a − b), B = b^2/(b − a). Answer: x + [a^2/(a − b)] ln(x − a) − [b^2/(a − b)] ln(x − b) + c. In the same way, ∫ x^3/((x − a)(x − b)(x − c)) dx = x + a^3 ln(x − a)/((a − b)(a − c)) + b^3 ln(x − b)/((b − a)(b − c)) + c^3 ln(x − c)/((c − a)(c − b)) + k. Forgetting the leading x is the usual trap."}]}]}]},{"number":"1.4","title":"Definite integrals and areas","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Definite integral:","bold":true},{"text":" ∫ from a to b of f(x) dx = [F(x)] from a to b = F(b) − F(a), where F is any anti-derivative. a is the "},{"text":"lower limit","bold":true},{"text":", b the "},{"text":"upper limit","bold":true},{"text":"."}]},{"text":[{"text":"The constant disappears:","bold":true},{"text":" [F(b) + c] − [F(a) + c] = F(b) − F(a)."}]},{"text":[{"text":"Properties:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"∫ from a to a of f(x) dx = 0."}]},{"text":[{"text":"∫ from a to b = −∫ from b to a (swapping limits changes the sign)."}]},{"text":[{"text":"∫ from a to b = ∫ from a to c + ∫ from c to b."}]},{"text":[{"text":"Odd function (f(−x) = −f(x)): ∫ from −a to a = 0."}]},{"text":[{"text":"Even function (f(−x) = f(x)): ∫ from −a to a = 2∫ from 0 to a."}]}]}]},{"text":[{"text":"Area under a curve","bold":true},{"text":" (f(x) ≥ 0 on [a, b]) = ∫ from a to b of f(x) dx."}]},{"text":[{"text":"Area bounded by a curve and the x-axis:","bold":true},{"text":" find where f(x) = 0; integrate between those roots."}]},{"text":[{"text":"Area between two curves:","bold":true},{"text":" solve f(x) = h(x) for the meeting points; area = ∫ (upper − lower) dx between them. Where the curves cross, split the interval and add the "},{"text":"sizes","bold":true},{"text":" of the pieces."}]},{"text":[{"text":"Improper case:","bold":true},{"text":" ∫ from 0 to 5 of (1/y) dy has "},{"text":"no finite value","bold":true},{"text":", because ln y has no finite value as y approaches 0."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"∫ from 2 to 3 of x^3 dx = [x^4/4] = 81/4 − 16/4 = 65/4."}]},{"text":[{"text":"∫ from 1 to 3 of x^2 dx = 27/3 − 1/3 = 26/3."}]},{"text":[{"text":"∫ from 2 to 4 of (7x^3 + x) dx = [7x^4/4 + x^2/2] = (448 + 8) − (28 + 2) = 426."}]},{"text":[{"text":"∫ from 1 to 2 of (x^(−2) + x) dx = [−1/x + x^2/2] = (−1/2 + 2) − (−1 + 1/2) = 2."}]},{"text":[{"text":"∫ from 6 to 10 of 1/(x + 2) dx = ln 12 − ln 8 = ln(3/2)."}]},{"text":[{"text":"∫ from −1 to 3 of 4/(2x + 3) dx = 2[ln(2x + 3)] = 2(ln 9 − ln 1) = 4.3944 (4 d.p.)."}]},{"text":[{"text":"∫ from 2 to 3 of e^(3x) dx = (1/3)(e^9 − e^6); ∫ from 2 to 3 of e^(2x) dx = (1/2)(e^6 − e^4) = (1/2)e^4(e^2 − 1)."}]},{"text":[{"text":"∫ from 1 to 2 of (e^(2x) + 3x^2) dx = (1/2)(e^4 − e^2) + 7 = (1/2)(e^4 − e^2 + 14). Similarly ∫ from 1 to 2 of (e^(3x) + 4x^2) dx = (1/3)(e^6 − e^3) + 28/3 = (1/3)(e^6 − e^3 + 28)."}]},{"text":[{"text":"∫ from 1 to 6 of 60/(3x + 2)^2 dx = [−20/(3x + 2)] = −20/20 + 20/5 = 3."}]},{"text":[{"text":"∫ from 1 to 3 of 2x/(1 + x^2) dx = ln 10 − ln 2 = ln 5; ∫ from 0 to 2 of x/(x^2 + 4) dx = (1/2)(ln 8 − ln 4) = (1/2) ln 2; ∫ from 0 to ln 2 of e^x/(1 + e^x) dx = ln 3 − ln 2 = ln 1.5."}]},{"text":[{"text":"∫ from 1 to 2 of 1/(x(x + 1)) dx = [ln x − ln(x + 1)] = (ln 2 − ln 3) − (0 − ln 2) = ln(4/3)."}]},{"text":[{"text":"∫ from −2 to 2 of x^3 dx = 4 − 4 = 0 (x^3 is odd)."}]}]},{"type":"paragraph","text":[{"text":"Areas.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Area under f(x) = 3x^(1/2) − 2 from 4 to 16 = [2x^(3/2) − 2x] = (128 − 32) − (16 − 8) = 88 square units."}]},{"text":[{"text":"Area under f(x) = x^(1/3) + 5 from 1 to 8 = [(3/4)x^(4/3) + 5x] = (12 + 40) − (3/4 + 5) = 185/4 square units."}]},{"text":[{"text":"Curve f(x) = 16 − x^2 and the x-axis: roots x = ±4. Area = [16x − x^3/3] from −4 to 4 = 128/3 − (−128/3) = 256/3 square units."}]},{"text":[{"text":"f(x) = 15 − 2x − x^2 and h(x) = 9 − x: 15 − 2x − x^2 = 9 − x gives x^2 + x − 6 = 0, so x = −3 or 2. Area = ∫ from −3 to 2 of (6 − x − x^2) dx = [6x − x^2/2 − x^3/3] = 22/3 − (−27/2) = 125/6 square units."}]},{"text":[{"text":"f(x) = 3x^3 − 3x and h(x) = x meet at x = −2/sqrt(3), 0, 2/sqrt(3). f − h = 3x^3 − 4x. Each piece has size 4/3, so total area = 8/3 square units. (Trap: integrating straight across gives 0, because the pieces cancel.)"}]}]}]},{"number":"1.5","title":"Total functions from marginal functions","mustKnow":[{"type":"list","ord$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 4, $study_guide$ered":false,"items":[{"text":[{"text":"Marginal = derivative of the total, so "},{"text":"total = integral of the marginal","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Total cost:","bold":true},{"text":" C(x) = ∫ MC dx + k. Fixed cost FC = C(0)."}]},{"text":[{"text":"Average cost:","bold":true},{"text":" AC = C(x)/x, x ≠ 0."}]},{"text":[{"text":"Total revenue:","bold":true},{"text":" R(x) = ∫ MR dx + k, with k found from R(0) = 0 (no sales, no revenue) unless another point is given."}]},{"text":[{"text":"Demand (price) function:","bold":true},{"text":" p = R(x)/x = average revenue (AR = price)."}]},{"text":[{"text":"Profit:","bold":true},{"text":" P(x) = R(x) − C(x); marginal profit = MR − MC."}]}]}]},{"text":[{"text":"Finding k:","bold":true},{"text":" substitute the given point (fixed cost, or a known cost/revenue at some x) into the integrated function. k equals the fixed cost only when C(0) has no other constant in it."}]},{"text":[{"text":"Change in total","bold":true},{"text":" when output rises from a to b = ∫ from a to b of (marginal) dx. No constant is needed."}]},{"text":[{"text":"Any rate:","bold":true},{"text":" if a quantity changes at rate f(t), the total change over [a, b] is ∫ from a to b of f(t) dt. Capital stock K = ∫ I dt (I = net investment); a curve with slope f'(x) is f(x) = ∫ f'(x) dx + c."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Finding the constant.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"With a polynomial MC, k is simply the fixed cost: MC = 9x^2 + 4x − 20, FC = ₦1,000 gives C(x) = 3x^3 + 2x^2 − 20x + 1000; MC = 25 + 30Q − 9Q^2, FC = 55 gives TC = 25Q + 15Q^2 − 3Q^3 + 55; MC = 20 − 0.04x + 0.003x^2, FC = ₦7,000 gives C = 20x − 0.02x^2 + 0.001x^3 + 7000."}]},{"text":[{"text":"An Aba shoe maker has MC = 6 + 10x − 6x^2 and producing a pair (x = 2) costs ₦12. C = 6x + 5x^2 − 2x^3 + k; 12 = 12 + 20 − 16 + k, so k = −4. C = 6x + 5x^2 − 2x^3 − 4 and AC = 6 + 5x − 2x^2 − 4/x."}]},{"text":[{"text":"MC = 5 + 16x − 3x^2, C(5) = ₦500: C(5) = 25 + 200 − 125 + k = 100 + k, so k = 400. MC = 3x^2 − 10x + 3, C(1) = ₦7: −1 + k = 7, so k = 8. MC = 8x^3, C(1) = 5: 2 + k = 5, so C = 2x^4 + 3."}]},{"text":[{"text":"Exponential MC:","bold":true},{"text":" MC = 12e^(0.5Q), FC = 36: TC = 24e^(0.5Q) + k; at Q = 0, 24 + k = 36, so TC = 24e^(0.5Q) + 12. MC = 16e^(0.4Q), FC = 100: TC = 40e^(0.4Q) + 60. MC = 2 + 5e^x, C(0) = 100: C = 2x + 5e^x + 95 and AC = 2 + 5e^x/x + 95/x. Here k is "},{"text":"not","bold":true},{"text":" the fixed cost, because e^0 = 1."}]},{"text":[{"text":"Root MC:","bold":true},{"text":" MC = 3(2x + 25)^(1/2), FC = ₦11,125. C = 3·(2x + 25)^(3/2)/(3/2 × 2) + k = (2x + 25)^(3/2) + k. C(0) = 125 + k = 11,125, so k = 11,000. C(300) = 625^(3/2) + 11,000 = 15,625 + 11,000 = ₦26,625."}]},{"text":[{"text":"MC = x/sqrt(x^2 + 2500), FC = ₦1,000: C = sqrt(x^2 + 2500) + k; 50 + k = 1000, so C = sqrt(x^2 + 2500) + 950."}]},{"text":[{"text":"MC = 14000/sqrt(7x + 4), FC = ₦18,000: C = 4000 sqrt(7x + 4) + k; 8000 + k = 18,000, k = 10,000. C(3) = 4000 × 5 + 10,000 = ₦30,000; AC = 30,000/3 = ₦10,000."}]},{"text":[{"text":"MC = x sqrt(x + 1), C(3) = ₦7,800: put u = x + 1, x = u − 1: ∫ (u^(3/2) − u^(1/2)) du gives C = (2/5)(x + 1)^(5/2) − (2/3)(x + 1)^(3/2) + k. At x = 3: 64/5 − 16/3 = 112/15, so k = 7800 − 112/15 = 116888/15."}]},{"text":[{"text":"MC proportional to x (MC = kx), FC = ₦5,000, C(50) = ₦5,625: C = kx^2/2 + 5000; 1250k = 625, k = 1/2, so C = x^2/4 + 5000."}]},{"text":[{"text":"MC in thousands: c'(x) = 4x^2 − 6x + 1, c(0) = 400. c(12) = (4/3)(1728) − 3(144) + 12 + 400 = 2304 − 432 + 12 + 400 = 2,284 thousand = ₦2,284,000."}]},{"text":[{"text":"MC = 0.1x^2 − 4x + 110, C(30) = ₦4,000: ∫ from 0 to 30 = 900 − 1800 + 3300 = 2,400 is variable cost, so FC = 4,000 − 2,400 = ₦1,600."}]},{"text":[{"text":"MC = 125 + 10x − x^2/9, FC = ₦250: C(15) = 1875 + 1125 − 125 + 250 = ₦3,125."}]}]},{"type":"paragraph","text":[{"text":"Change between two outputs.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"MC = 3q^2 − 60q + 400, first 2 units cost ₦900: ∫ from 2 to 5 = [q^3 − 30q^2 + 400q] = 1375 − 688 = 687, so C(5) = 900 + 687 = ₦1,587."}]},{"text":[{"text":"MC = 2Q + 6, TC(8) = 212: ∫ from 8 to 14 = [Q^2 + 6Q] = 280 − 112 = 168, so TC(14) = 380."}]},{"text":[{"text":"MR = 100 + 50x − 3x^2, 5 extra units after 5: ∫ from 5 to 10 = [100x + 25x^2 − x^3] = 2500 − 1000 = ₦1,500."}]},{"text":[{"text":"MR = 275 − x − 0.3x^2, output from 10 to 20: [275x − x^2/2 − 0.1x^3] = 4500 − 2600 = ₦1,900."}]},{"text":[{"text":"A firm with 200 workers makes 50,000 units a week; extra output per added worker is 300 − 5x^(2/3). For 64 more workers: ∫ from 0 to 64 = 300(64) − 3(64)^(5/3) = 19,200 − 3,072 = 16,128 additional units (66,128 in total; read which one is asked)."}]}]},{"type":"paragraph","text":[{"text":"Revenue and demand.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"MR = 500 − 4x, R(0) = 0: R = 500x − 2x^2. MR = 60 − 2Q − 2Q^2: TR = 60Q − Q^2 − (2/3)Q^3."}]},{"text":[{"text":"MR = 100 − 6Q: TR = 100Q − 3Q^2 and P = TR/Q = 100 − 3Q. MR = 20 − 2Q: TR = 20Q − Q^2, P = 20 − Q. MR = 6/sqrt(Q): TR = 12 sqrt(Q), P = 12/sqrt(Q)."}]},{"text":[{"text":"MR = 12 − 3x^2 + 4x: R = 12x + 2x^2 − x^3, p = 12 + 2x − x^2. MR = 20 − 5x + 3x^2: R = 20x − (5/2)x^2 + x^3. MR = 14 − 6x + 9x^2: p = 14 − 3x + 3x^2."}]},{"text":[{"text":"MR = 5 + 3x − x^2, R(6) = 112: R = 5x + (3/2)x^2 − (1/3)x^3 + k; 30 + 54 − 72 + k = 112, k = 100. R = 100 + 5x + (3/2)x^2 − (1/3)x^3; AR = 100/x + 5 + (3/2)x − (1/3)x^2."}]},{"text":[{"text":"MR = 5 + 6/(x + 2)^2: R = 5x − 6/(x + 2) + k; R(0) = −3 + k = 0, so R = 5x − 6/(x + 2) + 3."}]},{"text":[{"text":"MR = 6/(x − 3)^2 − 4: R = −6/(x − 3) − 4x + k; R(0) = 2 + k = 0, k = −2. p = R/x simplifies to p = 2/(3 − x) − 4."}]},{"text":[{"text":"MR = 4/(2x + 3)^2 − 1: R = −2/(2x + 3) − x + 2/3 = 4x/(3(2x + 3)) − x, so p = 4/(6x + 9) − 1."$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 5, $study_guide$}]},{"text":[{"text":"MR = 16 − x^2, MC = 3x^2 − 2x + 8, c(0) = ₦500: r = 16x − x^3/3, c = x^3 − x^2 + 8x + 500, profit p(x) = −(4/3)x^3 + x^2 + 8x − 500. Maximum revenue: MR = 0 at x = 4 (r'' = −2x < 0), r(4) = 64 − 64/3 = 128/3."}]}]},{"type":"paragraph","text":[{"text":"Other rates.","bold":true},{"text":" Net investment I = 40t^(3/5), K(0) = 75: K = 40·t^(8/5)/(8/5) + 75 = 25t^(8/5) + 75. Slope 3x^2 + 1 through (2, 6): f = x^3 + x + c, 10 + c = 6, so f(x) = x^3 + x − 4. Price changing at dp/dx = −135x/sqrt(9 + x^2) with p(4) = 30: p = −135 sqrt(9 + x^2) + k; −675 + k = 30, so p(x) = −135 sqrt(9 + x^2) + 705."}]}]},{"number":"1.6","title":"Surplus, sales, profitable life and income streams","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Equilibrium (x0, p0):","bold":true},{"text":" where demand price = supply price."}]},{"text":[{"text":"Consumer's surplus (CS)","bold":true},{"text":" = ∫ from 0 to x0 of d(x) dx − x0·p0: what consumers were willing to pay minus what they actually pay."}]},{"text":[{"text":"Producer's surplus (PS)","bold":true},{"text":" = x0·p0 − ∫ from 0 to x0 of s(x) dx: what producers actually receive minus what they were willing to accept."}]},{"text":[{"text":"If only a demand curve and a quantity x0 are given, first find p0 = d(x0)."}]},{"text":[{"text":"Total sales","bold":true},{"text":" over the first T days at sales rate f(t) = ∫ from 0 to T of f(t) dt."}]},{"text":[{"text":"Total inventory carrying cost","bold":true},{"text":" over a period T = c1 × ∫ from 0 to T of I(x) dx, where I(x) is the inventory held at time x and c1 is the carrying (holding) cost per unit per unit of time."}]},{"text":[{"text":"Profitable life:","bold":true},{"text":" a project or machine is profitable while R'(x) > C'(x) (or plan 2's rate exceeds plan 1's). Solve R'(x) = C'(x) for the end point N; "},{"text":"net earnings","bold":true},{"text":" = ∫ from 0 to N of [R'(x) − C'(x)] dx."}]},{"text":[{"text":"Income stream f(t)","bold":true},{"text":" for T years at rate r compounded continuously:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Total money flow = ∫ from 0 to T of f(t) dt"}]},{"text":[{"text":"Present value PV = ∫ from 0 to T of f(t) e^(−rt) dt"}]},{"text":[{"text":"Future value FV = ∫ from 0 to T of f(t) e^(r(T − t)) dt = e^(rT) × PV"}]}]}]},{"text":[{"text":"Continuous annuity:","bold":true},{"text":" P per year paid continuously at rate j compounded continuously for n years: F = ∫ from 0 to n of P e^(jt) dt = (P/j)(e^(jn) − 1)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Surplus.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand p = 20 − x − x^2 at x0 = 3: p0 = 20 − 3 − 9 = 8. CS = ∫ from 0 to 3 of (20 − x − x^2) dx − 3 × 8 = (60 − 4.5 − 9) − 24 = 45/2."}]},{"text":[{"text":"Demand p = 20 − 2x at x0 = 6: p0 = 8. CS = (120 − 36) − 48 = ₦36 (the triangle (1/2)(6)(20 − 8) gives the same)."}]},{"text":[{"text":"Demand p = 61 − x^2, supply p = 11 + x^2: 61 − x^2 = 11 + x^2, x0 = 5, p0 = 36, x0p0 = 180. CS = (305 − 125/3) − 180 = 250/3. PS = 180 − (55 + 125/3) = 250/3."}]},{"text":[{"text":"Chips (q in thousands): demand p = 90 − 0.1q^2, supply p = 50 + q + 0.2q^2. 0.3q^2 + q − 40 = 0, i.e. 3q^2 + 10q − 400 = 0 = (3q + 40)(q − 10), so q0 = 10, p0 = ₦80. CS = (900 − 100/3) − 800 = 66.67 thousand naira (2 d.p.). PS = 800 − (500 + 50 + 200/3) = 183.33 thousand naira."}]}]},{"type":"paragraph","text":[{"text":"Sales.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"f(t) = 200 − 90e^(−t): ∫ from 0 to 5 = [200t + 90e^(−t)] = 1000 + 90e^(−5) − 90 = 910.61 units (2 d.p.)."}]},{"text":[{"text":"f(x) = 100 − 90e^(−x), first four days, e^(−4) = 0.018: 400 + 90(0.018) − 90 = 311.62 units (with the exact e^(−4) it is 311.65)."}]}]},{"type":"paragraph","text":[{"text":"Profitable life.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Plan 1 earns at 220 + x^2 and plan 2 at 520 + 5x naira per year. Plan 2 is better while 520 + 5x > 220 + x^2, i.e. x^2 − 5x − 300 < 0, (x − 20)(x + 15) < 0, so for "},{"text":"20 years","bold":true},{"text":"."}]},{"text":[{"text":"A machine earns R'(x) = 14,560 − 20x^2 and costs C'(x) = 8,080 + 25x^2. Profitable while 6,480 − 45x^2 > 0, so x^2 < 144, N = 12 years. Net earnings = ∫ from 0 to 12 of (6,480 − 45x^2) dx = 77,760 − 25,920 = ₦51,840."}]},{"text":[{"text":"Depreciation at V'(t) = 500(t − 12) naira per year: ∫ from 0 to 5 = 500[t^2/2 − 12t] = 500(12.5 − 60) = −23,750, so the loss in value is ₦23,750."}]}]},{"type":"paragraph","text":[{"text":"Income streams and annuities.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Revenue flows into a fund at f(x) = 8,000x naira per year, 0 ≤ x ≤ 4, r = 10%."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Total flow = ∫ from 0 to 4 of 8000x dx = 4000(16) = ₦64,000."}]},{"text":[{"text":"PV = 8000 ∫ from 0 to 4 of x e^(−0.1x) dx. By parts, ∫ x e^(−0.1x) dx = −e^(−0.1x)(10x + 100). From 0 to 4: 100 − 140e^(−0.4) = 100 − 93.8448 = 6.15519. PV = 8000 × 6.15519 = ₦49,241.55."}]},{"text":[{"text":"FV = e^(0.4) × PV = 1.491825 × 49,241.55 = ₦73,459.76."}]}]}]},{"text":[{"text":"₦1,000 a year paid continuously at 10% for 6 years: F = (1000/0.1)(e^(0.6) − 1) = 10,000 × 0.822119 = ₦8,221 (nearest naira)."}]},{"text":[{"text":"Payment needed for ₦6,000 in 3 years at 6%: 6000 = (P/0.06)(e^(0.18) − 1) = P × 3.28695, so P = ₦1,825.40."}]},{"text":[{"text":"Depletion time: use is 50 trillion cubic feet a year growing at 3% continuously, reserves 2,200. ∫ from 0 to T of 50e^(0.03t) dt = (50/0.03)(e^(0.03T) − 1) = 2,200, so e^(0.03T) = 2.32 and T = ln 2.32/0.03 = 28.05 years. (44 years, from 2,200/50, ignores the growth.)"}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Integration reverses differentiation; always add c to an indefinite integral and check by differentiating."}]},{"text":[{"text":"Power r$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 6, $study_guide$ule: x^n gives x^(n+1)/(n + 1); 1/x gives ln x; e^(mx) gives e^(mx)/m; a^x gives a^x/ln a."}]},{"text":[{"text":"Expand products and divide quotients first; inside (ax + b), divide by a."}]},{"text":[{"text":"f'(x)/f(x) integrates to ln f(x); f'·f^n integrates to f^(n+1)/(n + 1)."}]},{"text":[{"text":"By parts: ∫ u dv = uv − ∫ v du; take u = ln x, otherwise u = the power of x."}]},{"text":[{"text":"Partial fractions: divide first if the fraction is improper, then cover up to find A, B."}]},{"text":[{"text":"Definite integral = F(b) − F(a); c cancels; odd functions over [−a, a] give 0; areas between crossing curves are added as sizes."}]},{"text":[{"text":"C = ∫ MC dx + k (C(0) = fixed cost); R = ∫ MR dx with R(0) = 0; demand p = R/x."}]},{"text":[{"text":"CS = ∫ d(x) dx − x0p0; PS = x0p0 − ∫ s(x) dx."}]},{"text":[{"text":"PV of a stream = ∫ f(t)e^(−rt) dt; FV = e^(rT) × PV; continuous annuity F = (P/j)(e^(jn) − 1)."}]}]}],"theory":{"itemId":"7c5f1877-bd7e-5928-be0b-41285fe8de6f","question":[{"type":"paragraph","text":[{"text":"A Lagos bakery's marginal cost is MC = 3x^2 − 4x + 5 naira per loaf, and its fixed cost is ₦200. Find the total cost function and the cost of producing 10 loaves."}]}]},"practice":[{"topic":"Integral Calculus Applications","named":false}]}},{"kind":"note","itemId":"653b5a32-57de-591e-b8b9-26e93e1c7318","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Algebraic, Exponential and Logarithmic Functions","body":"Functions, domain, range and composites; straight lines and linear business models; equations, identities, inequalities, quadratics and simultaneous equations; the vertex of a parabola in revenue, profit and cost problems; laws of exponents and logarithms; exponential growth and decay models.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"Functions, domain, range and composites; straight lines and linear business models; equations, identities, inequalities, quadratics and simultaneous equations; the vertex of a parabola in revenue, profit and cost problems; laws of exponents and logarithms; exponential growth and decay models."}],"lessons":[{"number":"2.1","title":"Functions, domain, range and composites","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Function:","bold":true},{"text":" a rule that assigns to each element x in the domain D "},{"text":"exactly one","bold":true},{"text":" element f(x) in the range R (two x values may share a value; one x may not have two)."}]},{"text":[{"text":"Domain:","bold":true},{"text":" the x values for which the function can be evaluated. "},{"text":"Range:","bold":true},{"text":" the values f(x) takes. x is "},{"text":"independent","bold":true},{"text":", y "},{"text":"dependent","bold":true},{"text":"."}]},{"text":[{"text":"Domain rules:","bold":true},{"text":" denominator ≠ 0; inside an even root ≥ 0; inside ln or log > 0. Price and quantity cannot be negative."}]},{"text":[{"text":"Composite:","bold":true},{"text":" g[h(x)] puts h(x) wherever u appears in g(u); (f o g)(x) = f[g(x)], inside first."}]},{"text":[{"text":"Piecewise:","bold":true},{"text":" use the formula whose interval contains x. "},{"text":"Two variables:","bold":true},{"text":" z = f(x, y), domain = all workable pairs."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Evaluate:","bold":true},{"text":" f(x) = x^3 − 2x^2 + 3x + 100, f(2) = 8 − 8 + 6 + 100 = "},{"text":"106","bold":true},{"text":"."}]},{"text":[{"text":"Domains:","bold":true},{"text":" 1/(x − 3): all x "},{"text":"except 3","bold":true},{"text":". sqrt(x − 2): "},{"text":"x ≥ 2","bold":true},{"text":". e^(sqrt x) + ln y: "},{"text":"x ≥ 0, y > 0","bold":true},{"text":", and f(0, 1) = e^0 + ln 1 = "},{"text":"1","bold":true},{"text":"."}]},{"text":[{"text":"Business domain:","bold":true},{"text":" R(p) = p(600 − 20p) needs p ≥ 0 and q = 600 − 20p ≥ 0, so "},{"text":"0 ≤ p ≤ 30","bold":true},{"text":"."}]},{"text":[{"text":"Range:","bold":true},{"text":" S(t) = 500 − 300e^(−0.4t), t ≥ 0: S(0) = 200, and S rises towards 500 without reaching it: "},{"text":"200 ≤ S < 500","bold":true},{"text":"."}]},{"text":[{"text":"Composite:","bold":true},{"text":" g(u) = u^2 + 3u + 1, h(x) = x + 1. g[h(x)] = (x + 1)^2 + 3(x + 1) + 1 = "},{"text":"x^2 + 5x + 5","bold":true},{"text":". f(x) = 2x + 3, g(x) = x^2 − 1: g(3) = 8, f(8) = "},{"text":"19","bold":true},{"text":"."}]},{"text":[{"text":"In context:","bold":true},{"text":" C(p) = 0.5p + 1, p(t) = 10 + 0.1t^2 give C(t) = "},{"text":"6 + 0.05t^2","bold":true},{"text":"; C = 6.8 gives t^2 = 16, "},{"text":"t = 4 years","bold":true},{"text":". q(t) = 25t, C(q) = 0.1q^2 + 12q + 5,000: 8 hours gives q = 200, C = 4,000 + 2,400 + 5,000 = "},{"text":"₦11,400","bold":true},{"text":"."}]},{"text":[{"text":"Change:","bold":true},{"text":" C(x) = 20,000 + 150x + 0.4x^2: C(60) − C(50) = 30,440 − 28,500 = "},{"text":"₦1,940","bold":true},{"text":"."}]},{"text":[{"text":"Piecewise:","bold":true},{"text":" commission 6% up to ₦300,000, else ₦6,000 + 4%. On ₦500,000: 6,000 + 20,000 = "},{"text":"₦26,000","bold":true},{"text":" (₦30,000 uses the wrong piece)."}]},{"text":[{"text":"Tiered bill:","bold":true},{"text":" ₦1.22, ₦10, ₦50 per 100 cubic feet for the first 1,200, next 1,200, and the rest. 3,000 cubic feet: 14.64 + 120 + 300 = "},{"text":"₦434.64","bold":true},{"text":"."}]},{"text":[{"text":"Building a model","bold":true},{"text":" (write the quantity, then remove the extra variable using the constraint):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Picnic area xy = 5,000, side x unfenced: F = x + 2y = "},{"text":"x + 10,000/x","bold":true},{"text":"."}]},{"text":[{"text":"Can, volume 24π: h = 24/r^2. Ends 2πr^2 × ₦3 = 6πr^2; side 2πrh × ₦2 = 96π/r. "},{"text":"C(r) = 6πr^2 + 96π/r","bold":true},{"text":"."}]},{"text":[{"text":"Cable, river 900 m, factory 3,000 m downstream: water sqrt(810,000 + x^2) at ₦5, land (3,000 − x) at ₦4. "},{"text":"C(x) = 4(3,000 − x) +$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 7, $study_guide$ 5 sqrt(810,000 + x^2)","bold":true},{"text":"."}]}]}]}]}]},{"number":"2.2","title":"Linear functions and straight-line models","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Linear function:","bold":true},{"text":" y = mx + b; "},{"text":"constant rate","bold":true},{"text":" of change; straight-line graph."}]},{"text":[{"text":"Slope:","bold":true},{"text":" m = (y2 − y1)/(x2 − x1), the change in y per unit rise in x. "},{"text":"y-intercept:","bold":true},{"text":" b, y at x = 0."}]},{"text":[{"text":"Point-slope form:","bold":true},{"text":" y − y0 = m(x − x0)."}]},{"text":[{"text":"To read slope and intercept, make y the subject: 5y + 2x = 20 gives y = −(2/5)x + 4, slope "},{"text":"−2/5","bold":true},{"text":", intercept "},{"text":"4","bold":true},{"text":"."}]},{"text":[{"text":"Cost line:","bold":true},{"text":" C(x) = fixed cost + (variable cost per unit)x. In C(x) = 45,000 + 350x, ₦45,000 is the fixed cost and each extra unit adds ₦350."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Slope through (−3, 4) and (5, −8): (−8 − 4)/(5 − (−3)) = −12/8 = "},{"text":"−1.5","bold":true},{"text":". A line with slope −3.1 and intercept 10: "},{"text":"y = −3.1x + 10","bold":true},{"text":"."}]},{"text":[{"text":"Rising price:","bold":true},{"text":" bread rises ₦2 a month, ₦106 on 1 November (x = 10 months after 1 January): 106 = 20 + b, so p = 2x + 86, "},{"text":"₦86","bold":true},{"text":" on 1 January. Soft drink ₦156: p = 2x + "},{"text":"136","bold":true},{"text":". Petrol ₦103 on 1 June, 1 October is 4 months later: "},{"text":"₦111","bold":true},{"text":"."}]},{"text":[{"text":"Two points:","bold":true},{"text":" reservoir 200 (day 12), 164 (day 21): slope −4 a day, day 8 = "},{"text":"216 million gallons","bold":true},{"text":". Scores 575 (1986), 545 (1991): −6 a year, 1996 = "},{"text":"515","bold":true},{"text":"."}]},{"text":[{"text":"Cost:","bold":true},{"text":" ₦85,000 for 100 copies, ₦130,000 for 250: m = 45,000/150 = 300, b = 85,000 − 30,000: "},{"text":"C = 300x + 55,000","bold":true},{"text":"."}]},{"text":[{"text":"Straight-line depreciation:","bold":true},{"text":" ₦2,400,000 to ₦1,500,000 in 3 years is ₦300,000 a year; zero after "},{"text":"8 years","bold":true},{"text":"."}]},{"text":[{"text":"Linear demand:","bold":true},{"text":" 1,200 bags at ₦500, 900 at ₦650: slope −2, x = 2,200 − 2p, zero at "},{"text":"₦1,100","bold":true},{"text":"."}]},{"text":[{"text":"Two plans:","bold":true},{"text":" A = 25 + 0.60x, B = 30 + 0.50x. Equal when 0.1x = 5, "},{"text":"x = 50","bold":true},{"text":". A (lower fixed charge) is cheaper below 50, B (lower rate) above. A lower rate is not always cheaper."}]}]}]},{"number":"2.3","title":"Equations, identities, inequalities and systems","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Equation:","bold":true},{"text":" true only for "},{"text":"particular values","bold":true},{"text":" of its variable(s). "},{"text":"Identity:","bold":true},{"text":" true for "},{"text":"all values","bold":true},{"text":", e.g. (x + 2)^2 = x^2 + 4x + 4, x^2 + 2x = x(x + 2)."}]},{"text":[{"text":"Inequality:","bold":true},{"text":" two expressions joined by >, <, ≥ or ≤, e.g. 3x + 1 > 0."}]},{"text":[{"text":"Degree","bold":true},{"text":" = highest power (2x^5 − 3x^2 + 1 = 0 is degree 5; 5 − 6x + 4x^7 − 2x^10 is degree 10). 1 linear, 2 quadratic, 3 cubic, 4 bi-quadratic."}]},{"text":[{"text":"Linear equation:","bold":true},{"text":" no powers above 1, no products of variables. "},{"text":"System of linear equations:","bold":true},{"text":" e.g. 2x + 3y = 7 and x − y = 1 (x^2, xy or 1/y make it non-linear)."}]},{"text":[{"text":"Multiplying or dividing an inequality by a "},{"text":"negative","bold":true},{"text":" number "},{"text":"reverses","bold":true},{"text":" the sign."}]},{"text":[{"text":"Quadratic formula:","bold":true},{"text":" ax^2 + bx + c = 0 gives x = (−b ± sqrt(b^2 − 4ac))/(2a). "},{"text":"Discriminant","bold":true},{"text":" b^2 − 4ac: > 0 two real roots; = 0 one repeated root; < 0 no real roots."}]},{"text":[{"text":"Roots α, β:","bold":true},{"text":" α + β = −b/a, αβ = c/a. The equation with roots α and β is x^2 − (α + β)x + αβ = 0."}]},{"text":[{"text":"Useful identities: α^2 + β^2 = (α + β)^2 − 2αβ; x^2 − y^2 = (x + y)(x − y)."}]},{"text":[{"text":"Systems:","bold":true},{"text":" elimination or substitution (substitution when one equation is non-linear)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Inequalities:","bold":true},{"text":" x − 9 > 3x + 1 gives −2x > 10, flip: "},{"text":"x < −5","bold":true},{"text":". 4(3x + 2) ≥ 2x gives "},{"text":"x ≥ −4/5","bold":true},{"text":". 5(3 − 2x) < 3(4 − 3x) gives −x < −3, "},{"text":"x > 3","bold":true},{"text":"."}]},{"text":[{"text":"Word inequality:","bold":true},{"text":" x pencils at ₦5, (x + 4) pens at ₦8, total ≤ ₦97: 13x + 32 ≤ 97, x ≤ "},{"text":"5","bold":true},{"text":"."}]},{"text":[{"text":"Quadratics:","bold":true},{"text":" x^2 − 8x + 15 = (x − 3)(x − 5), x = "},{"text":"3 or 5","bold":true},{"text":". 2x^2 − 5x = 6x + 10 becomes 2x^2 − 11x − 10 = 0: x = (11 ± sqrt(121 + 80))/4 = "},{"text":"(11 ± sqrt 201)/4","bold":true},{"text":". x^2 − 10x − 9 = 0: x = (10 ± sqrt 136)/2 = "},{"text":"5 ± sqrt 34","bold":true},{"text":"."}]},{"text":[{"text":"Forming equations:","bold":true},{"text":" roots of x^2 − 3x − 10 = 0 have a + b = 3, ab = −10. For roots a^2, b^2: sum = 9 − 2(−10) = 29, product = (ab)^2 = 100, giving "},{"text":"x^2 − 29x + 100 = 0","bold":true},{"text":". For 2x^2 − 4x + 1 = 0 (a + b = 2, ab = 1/2), roots a^2 + b and a + b^2: sum = (a^2 + b^2) + (a + b) = (4 − 1) + 2 = 5; product = a^3 + a^2b^2 + ab + b^3 = (a + b)^3 − 3ab(a + b) + (ab)^2 + ab = 8 − 3 + 1/4 + 1/2 = 23/4. Equation x^2 − 5x + 23/4 = 0, i.e. "},{"text":"4x^2 − 20x + 23 = 0","bold":true},{"text":"."}]},{"text":[{"text":"Fractions:","bold":true},{"text":" (x + 3)/(x + 2) + (x − $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 8, $study_guide$3)/(x − 2) = (2x − 3)/(x − 1). Left side = (2x^2 − 12)/(x^2 − 4); cross-multiply and simplify: x^2 − 4x = 0, "},{"text":"x = 0 or 4","bold":true},{"text":"."}]},{"text":[{"text":"Elimination:","bold":true},{"text":" 2x + y = 11, 3x + 5y = 27. Five times the first minus the second: 7x = 28, "},{"text":"x = 4, y = 3","bold":true},{"text":"."}]},{"text":[{"text":"Substitution (non-linear):","bold":true},{"text":" x + y = 5 and x^2 + y^2 = 25. Since (x + y)^2 = 25, 2xy = 0: "},{"text":"(0, 5) or (5, 0)","bold":true},{"text":". 2x + 3y = 5, xy = 1: y = 1/x gives 2x^2 − 5x + 3 = 0, x = 1 or 3/2: "},{"text":"(1, 1) or (3/2, 2/3)","bold":true},{"text":". 3x^2 − 5x − 3y = −4 with 3y = 10 − 2x: 3x^2 − 3x − 6 = 0, x = 2 or −1: "},{"text":"(2, 2) or (−1, 4)","bold":true},{"text":"."}]},{"text":[{"text":"Word systems:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"₦10,000 in bonds at 7% and 10% earning ₦820: x + y = 10,000, 0.07x + 0.10y = 820, so −0.03x = −180: "},{"text":"₦6,000 at 7%, ₦4,000 at 10%","bold":true},{"text":"."}]},{"text":[{"text":"Chairs (20 min, ₦2), tables (30 min, ₦1), using 600 min and ₦40: 20x + 30y = 600, 2x + y = 40: "},{"text":"15 chairs, 10 tables","bold":true},{"text":"."}]},{"text":[{"text":"Digits a + b = 12; reversing loses 18, so 9(a − b) = 18, a − b = 2: "},{"text":"75","bold":true},{"text":"."}]},{"text":[{"text":"Batsman (198 runs in x matches, then 42 more, so 240 in x + 1): 240/(x + 1) = 198/x + 2 clears to x^2 − 20x + 99 = 0, "},{"text":"x = 9 or 11","bold":true},{"text":"."}]},{"text":[{"text":"27^x = 9^y gives 3x = 2y; 81 = 243 × 3x gives x = 1/9, y = 1/6."}]}]}]}]}]},{"number":"2.4","title":"Quadratic functions: vertex, intercepts and business use","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"y = ax^2 + bx + c is a "},{"text":"parabola","bold":true},{"text":": opens "},{"text":"upward","bold":true},{"text":" if a > 0 (vertex is a minimum), "},{"text":"downward","bold":true},{"text":" if a < 0 (vertex is a maximum)."}]},{"text":[{"text":"Vertex:","bold":true},{"text":" x = −b/(2a); substitute to get y."}]},{"text":[{"text":"x-intercepts:","bold":true},{"text":" solve ax^2 + bx + c = 0. "},{"text":"y-intercept:","bold":true},{"text":" c."}]},{"text":[{"text":"Revenue","bold":true},{"text":" R = xp. "},{"text":"Profit","bold":true},{"text":" P = R − C. "},{"text":"Break-even:","bold":true},{"text":" P = 0 (R = C). For P(x) = ax^2 + bx + c with a < 0, the vertex gives "},{"text":"maximum profit","bold":true},{"text":" and the roots are the "},{"text":"break-even outputs","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"y = x^2 − 6x + 4: vertex x = 6/2 = 3, y = 9 − 18 + 4 = −5, vertex "},{"text":"(3, −5)","bold":true},{"text":", minimum. Intercepts: x = (6 ± sqrt(36 − 16))/2 = "},{"text":"3 ± sqrt 5","bold":true},{"text":"."}]},{"text":[{"text":"Maximum revenue:","bold":true},{"text":" R = 1,200x − 4x^2: x = 1,200/8 = 150, R = "},{"text":"₦90,000","bold":true},{"text":"."}]},{"text":[{"text":"Best price:","bold":true},{"text":" p = 900 − 3x, R = 900x − 3x^2: x = 150, p = "},{"text":"₦450","bold":true},{"text":" (₦67,500 is the revenue)."}]},{"text":[{"text":"Break-even:","bold":true},{"text":" −2x^2 + 240x − 4,000 = 0 becomes x^2 − 120x + 2,000 = 0: "},{"text":"x = 20 and 100","bold":true},{"text":" (maximum profit halfway, x = 60)."}]},{"text":[{"text":"Minimum average cost:","bold":true},{"text":" AC = 0.5x^2 − 40x + 1,000: x = 40, AC = 800 − 1,600 + 1,000 = "},{"text":"₦200 per unit","bold":true},{"text":"."}]},{"text":[{"text":"No break-even:","bold":true},{"text":" P = −x^2 + 40x − 500 (₦ thousands). Vertex x = 20, P = −400 + 800 − 500 = −100. The best result is a "},{"text":"loss of ₦100,000","bold":true},{"text":", and b^2 − 4ac = 1,600 − 2,000 < 0, so the firm never breaks even."}]}]}]},{"number":"2.5","title":"Exponents and logarithms","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Laws of exponents:","bold":true},{"text":" a^0 = 1; a^x · a^y = a^(x+y); a^x / a^y = a^(x−y); (a^x)^y = a^(xy); (ab)^x = a^x b^x; (a/b)^x = a^x / b^x; a^(−n) = 1/a^n; a^(m/n) = (n-th root of a)^m."}]},{"text":[{"text":"Logarithm:","bold":true},{"text":" log_b N = x means "},{"text":"b^x = N","bold":true},{"text":" (b > 0, b ≠ 1, N > 0)."}]},{"text":[{"text":"Common logarithm","bold":true},{"text":" (Briggsian): base 10, written log x. "},{"text":"Natural logarithm","bold":true},{"text":" (Napierian, after John Napier): base e ≈ 2.71828, written ln x. No base written means base 10."}]},{"text":[{"text":"Relation:","bold":true},{"text":" ln x = log x / log e = log x / 0.4343 = "},{"text":"2.3026 log x","bold":true},{"text":"."}]},{"text":[{"text":"Laws of logarithms:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"log_a 1 = 0"}]},{"text":[{"text":"log_a a = 1"}]},{"text":[{"text":"log(MN) = log M + log N"}]},{"text":[{"text":"log(M/N) = log M − log N"}]},{"text":[{"text":"log(M^k) = k log M"}]},{"text":[{"text":"log_a b = 1/log_b a"}]}]}]},{"text":[{"text":"Change of base:","bold":true},{"text":" log_a N = log N / log a = ln N / ln a"}]},{"text":[{"text":"Not a law:","bold":true},{"text":" log(M + N) ≠ log M + log N."}]},{"text":[{"text":"Inverses:","bold":true},{"text":" e^(ln x) = x, ln(e^x) = x, 10^(log x) = x. So 10^(log 5) = 5."}]},{"text":[{"text":"ln x:","bold":true},{"text":" defined only for x > 0; ln 1 = 0; negative for 0 < x < 1, positive for x > 1."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exponents:","bold":true},{"text":" (2^3)^2 = 64; 121^0.5 = 11; 16^(−3/4) = 1/2^3 = "},{"text":"1/8","bold":true},{"text":". 32^(3/5) × 125^(−2/3) = 2^3 × 5^(−2) = "},{"text":"8/25","bold":true},{"text":". 3x·x^(−2)y^5/(4x^4 y^2) = "},{"text":"3y^3/(4x^5)","bold":true},{"text":". [1 − {1 − (1 − x^3)^(−1)}^(−1)]^(1/3): inner bracket −x^3/(1 − x^3), reciprocal −(1 − x^3)$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 9, $study_guide$/x^3, 1 minus that = 1/x^3, cube root "},{"text":"1/x","bold":true},{"text":". 10^(1/5) × 10^(1/3) ÷ (10^(−2/3) × 10^(−1)) = 10^2.2 = "},{"text":"158.49","bold":true},{"text":"."}]},{"text":[{"text":"Same base:","bold":true},{"text":" 4^(x+1) = 8^(x−1) gives 2^(2x+2) = 2^(3x−3), so "},{"text":"x = 5","bold":true},{"text":"."}]},{"text":[{"text":"By definition:","bold":true},{"text":" log_6(6 sqrt 6) = log_6 6^(3/2) = "},{"text":"3/2","bold":true},{"text":". log_5(cube root 5 × sqrt 5) = 1/3 + 1/2 = "},{"text":"5/6","bold":true},{"text":". log_x 25 = 2: "},{"text":"x = 5","bold":true},{"text":". log_x 81 = 4: "},{"text":"x = 3","bold":true},{"text":". (2 sqrt 5)^4 = 400, so log_(2 sqrt 5) 400 = "},{"text":"4","bold":true},{"text":". log_2 sqrt 6 + log_2 sqrt(2/3) = log_2 sqrt 4 = "},{"text":"1","bold":true},{"text":"."}]},{"text":[{"text":"Nested logs","bold":true},{"text":" (inside out): log_3 27^3 = 9, log_3 9 = 2, log_2 2 = 1, log_2 1 = "},{"text":"0","bold":true},{"text":". Reverse: log_2{log_3(log_2 x)} = 1 gives log_3(log_2 x) = 2, log_2 x = 9, "},{"text":"x = 512","bold":true},{"text":"."}]},{"text":[{"text":"Log equations","bold":true},{"text":" (reject answers making a log argument or base invalid): log_2(x + 3) + log_2(x − 3) = 4 gives x^2 − 9 = 16, "},{"text":"x = 5 only","bold":true},{"text":" (−5 rejected). log_x(4x + 3) − log_x 4 = 2 gives 4x^2 − 4x − 3 = 0, "},{"text":"x = 3/2 only","bold":true},{"text":" (no negative base). log_x 3 + log_x 9 + log_x 729 = 9 log_x 3 = 9: "},{"text":"x = 3","bold":true},{"text":"."}]},{"text":[{"text":"Expanding:","bold":true},{"text":" log x = 0.5, log y = 1.5, log z = 3: log(xy/z^(1/3)) = 0.5 + 1.5 − 1 = "},{"text":"1","bold":true},{"text":". log a = 0.3, log b = 2.8642, log c = 1.7642: log(a^3 b^(1/2)/c) = 0.9 + 1.4321 − 1.7642 = "},{"text":"0.5679","bold":true},{"text":". ln(x^3 sqrt y/z^2) = "},{"text":"3 ln x + (1/2) ln y − 2 ln z","bold":true},{"text":"."}]},{"text":[{"text":"From log 2 = 0.3010, log 3 = 0.4771:","bold":true},{"text":" log 7.2 = log(2^3 × 3^2/10) = 0.9030 + 0.9542 − 1 = "},{"text":"0.8572","bold":true},{"text":". log_8 25 = 2 log 5/(3 log 2) = 2(0.6990)/0.9030 = "},{"text":"1.548","bold":true},{"text":" (log 5 = 1 − log 2)."}]},{"text":[{"text":"Simplify:","bold":true},{"text":" 7 log(16/15) + 5 log(25/24) + 3 log(81/80). Write in primes: 16/15 = 2^4/(3·5), 25/24 = 5^2/(2^3·3), 81/80 = 3^4/(2^4·5). Powers of 2: 28 − 15 − 12 = 1; of 3: −7 − 5 + 12 = 0; of 5: −7 + 10 − 3 = 0. Result "},{"text":"log 2","bold":true},{"text":"."}]},{"text":[{"text":"Solving a^x = N:","bold":true},{"text":" x = log N/log a. 3^x = 8: 0.9031/0.4771 = "},{"text":"1.893","bold":true},{"text":". 9^x = 2: "},{"text":"0.3155","bold":true},{"text":". 10^x = 8: "},{"text":"0.9031","bold":true},{"text":". log_5 40 = ln 40/ln 5 = "},{"text":"2.2920","bold":true},{"text":"; log_4 7 = "},{"text":"ln 7/ln 4","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" 3(2^x) = 48 gives 2^x = 16, x log 2 = log 16, so x = log 16 "},{"text":"÷","bold":true},{"text":" log 2 = 4; writing log 16 − log 2 is the error."}]},{"text":[{"text":"10,000(1 + i)^10 = 30,000: 1 + i = 3^(0.1), "},{"text":"i = 0.1161","bold":true},{"text":". ln(1 + x) = −0.5: x = e^(−0.5) − 1 = "},{"text":"−0.3935","bold":true},{"text":"."}]},{"text":[{"text":"Mixed bases:","bold":true},{"text":" 2^x · 3^(2x+1) = 7^(4x+3). Logs: x log 2 + (2x + 1) log 3 = (4x + 3) log 7, so x = (3 log 7 − log 3)/(log 2 + 2 log 3 − 4 log 7) = 2.0582/(−2.1252) = "},{"text":"−0.9685","bold":true},{"text":"."}]},{"text":[{"text":"Quadratic in e^x:","bold":true},{"text":" e^(2x) − 5e^x + 6 = 0; u = e^x gives u = 2 or 3, x = "},{"text":"0.6931 or 1.0986","bold":true},{"text":"."}]},{"text":[{"text":"Computing with logs:","bold":true},{"text":" 1000(1.06)^110.5: log = 3 + 110.5 × 0.025306 = 5.79631, antilog ≈ "},{"text":"625,600","bold":true},{"text":". 789.45^(1/8): 2.89732 ÷ 8 = 0.36217, antilog "},{"text":"2.3023","bold":true},{"text":"."}]}]}]},{"number":"2.6","title":"Exponential functions and growth and decay models","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exponential function:","bold":true},{"text":" f(x) = b^x where the base b is a positive constant (b ≠ 1) and the "},{"text":"variable is the exponent","bold":true},{"text":". x^10 is not exponential (the variable is the base; that is a power function)."}]},{"text":[{"text":"Graph of b^x:","bold":true},{"text":" passes through "},{"text":"(0, 1)","bold":true},{"text":"; "},{"text":"positive for every x","bold":true},{"text":" (never negative); increasing if b > 1, decreasing if 0 < b < 1; tends to 0 on one side."}]},{"text":[{"text":"e","bold":true},{"text":" = limit of "},{"text":"(1 + 1/n)^n","bold":true},{"text":" as n grows without bound ≈ 2.71828."}]},{"text":[{"text":"Discrete growth:","bold":true},{"text":" y = a(1 + r)^t (a = starting value, r = rate per period). "},{"text":"Decay (reducing balance):","bold":true},{"text":" y = a(1 − r)^t."}]},{"text":[{"text":"Continuous growth:","bold":true},{"text":" y = ae^(kt), k > 0; "},{"text":"decay","bold":true},{"text":" y = ae^(−kt). Equivalent annual rate: r = e^k − 1."}]},{"text":[{"text":"Doubling time:","bold":true},{"text":" discrete t = ln 2/ln(1 + r); continuous t = ln 2/k. "},{"text":"Half-life:","bold":true},{"text":" t = ln 2/k. "},{"text":"Tripling:","bold":true},{"text":" replace 2 with 3."}]},{"text":[{"text":"Rate from two values:","bold":true},{"text":" k = ln(y2/y1)/(t2 − t1); r = (y2/y1)^(1/(t2 − t1)) − 1."}]},{"text":[{"text":"Log-linear:","bold":true},{"text":" if y = ae^(kt), then ln y = ln a + kt, a straight line with "},{"text":"slope k","bold":true},{"text":" and intercept "},{"text":"ln a","bold":true},{"text":"."}]},{"text":[{"text":"Saturation models:","bold":true},{"text":" y = M(1 − e^(−kt)) starts at 0 and rises towards M but never passes it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading a $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 10, $study_guide$model:","bold":true},{"text":" N(t) = 25,000(1.06)^t: 25,000 customers now, growing "},{"text":"6%","bold":true},{"text":" a year (not a fixed 1,500). 500e^(−0.3t) is decay; 500 − 0.3t is linear."}]},{"text":[{"text":"Discrete:","bold":true},{"text":" Ogun State town, 250,000 in 2020 at 3%: 2026 (t = 6) gives 250,000(1.03)^6 = "},{"text":"298,513","bold":true},{"text":". ₦4,500,000 van losing 15% a year: 4,500,000(0.85)^4 = "},{"text":"₦2,349,028","bold":true},{"text":"."}]},{"text":[{"text":"Doubling and tripling:","bold":true},{"text":" 4% a year: ln 2/ln 1.04 = "},{"text":"17.67 years","bold":true},{"text":". Tripling at 9%: ln 3/ln 1.09 = "},{"text":"12.75 years","bold":true},{"text":". 5,000e^(0.08t) doubles in ln 2/0.08 = "},{"text":"8.66 months","bold":true},{"text":"."}]},{"text":[{"text":"Continuous:","bold":true},{"text":" 2,000e^(0.12 × 5) = "},{"text":"3,644 units","bold":true},{"text":". V0 e^(−0.25t) halves in ln 2/0.25 = "},{"text":"2.77 years","bold":true},{"text":". Halving every 5 years: k = ln 2/5 = "},{"text":"0.1386","bold":true},{"text":". ae^(0.08t): r = e^0.08 − 1 = "},{"text":"8.33%","bold":true},{"text":"."}]},{"text":[{"text":"Rate from data:","bold":true},{"text":" ₦40 million (2021) to ₦58 million (2025): k = ln 1.45/4 = "},{"text":"9.29%","bold":true},{"text":". Rice ₦38,000 (2023) to ₦64,000 (2026): r = (64/38)^(1/3) − 1 = "},{"text":"18.98%","bold":true},{"text":". GDP ₦100 billion (1990) to ₦165 billion (2000) is a factor 1.65 per decade: 2010 = "},{"text":"₦272.25 billion","bold":true},{"text":"."}]},{"text":[{"text":"Time to a level:","bold":true},{"text":" 1.2 million (2015), 1.5 million (2020): k = ln 1.25/5 = 0.04463; 2 million at t = ln(2/1.2)/0.04463 = "},{"text":"11.45 years","bold":true},{"text":"."}]},{"text":[{"text":"Base 10:","bold":true},{"text":" log y = 3 + 0.05t gives growth factor 10^0.05 = 1.1220, so "},{"text":"12.20%","bold":true},{"text":" a year."}]},{"text":[{"text":"Advertising response:","bold":true},{"text":" R = 1 − e^(−0.05t), t = 10: 1 − 0.6065 = "},{"text":"39.35%","bold":true},{"text":"."}]},{"text":[{"text":"Credit collections:","bold":true},{"text":" C = 0.92(1 − e^(−0.1t)), t = 3: 0.92(1 − 0.7408) = "},{"text":"23.84%","bold":true},{"text":"; as t grows, C approaches "},{"text":"92%","bold":true},{"text":", never 100%."}]},{"text":[{"text":"Malt drink:","bold":true},{"text":" 50,000(1 − e^(−0.3t)) = 40,000 gives e^(−0.3t) = 0.2, t = ln 5/0.3 = "},{"text":"5.36 months","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A function gives each x exactly one value; domain excludes zero denominators, negative even-root arguments and non-positive log arguments."}]},{"text":[{"text":"Composite g[h(x)]: substitute h(x) for u; work inside out."}]},{"text":[{"text":"Line: y = mx + b, slope = rise/run; fixed cost is the intercept, variable cost the slope."}]},{"text":[{"text":"Equation: true for some values; identity: true for all. Dividing an inequality by a negative flips the sign."}]},{"text":[{"text":"Quadratic formula, sum −b/a and product c/a of roots, x^2 − (sum)x + product = 0."}]},{"text":[{"text":"Vertex at x = −b/(2a): maximum revenue or profit, minimum average cost; profit roots are break-even points."}]},{"text":[{"text":"log_b N = x means b^x = N; ln = base e (Napierian), log = base 10 (Briggsian); ln x = 2.3026 log x; log(M + N) is not log M + log N."}]},{"text":[{"text":"y = a(1 + r)^t and y = ae^(kt); doubling ln 2/ln(1 + r) or ln 2/k; r = e^k − 1; ln y against t is a line of slope k."}]}]}],"theory":{"itemId":"b23c3ff2-fc70-5fb5-8da8-8f909c7bc704","question":[{"type":"paragraph","text":[{"text":"A generator bought for ₦1,200,000 loses 20% of its value each year (reducing balance). After how many whole years does its value first fall below ₦400,000?"}]}]},"practice":[{"topic":"Algebraic, Exponential and Logarithmic Functions","named":false}]}},{"kind":"note","itemId":"94922e51-b8d1-5993-9da4-777384cd0a7d","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Differentiation and Marginal Analysis","body":"The meaning and notations of the derivative and the first principle; the rules of differentiation (power, product, quotient, chain, exponential, logarithmic, higher derivatives); implicit and logarithmic differentiation; rates of change, percentage rates and approximation; marginal cost, revenue, profit and propensities; elasticity of demand and of cost.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The meaning and notations of the derivative and the first principle; the rules of differentiation (power, product, quotient, chain, exponential, logarithmic, higher derivatives); implicit and logarithmic differentiation; rates of change, percentage rates and approximation; marginal cost, revenue, profit and propensities; elasticity of demand and of cost."}],"lessons":[{"number":"3.1","title":"Meaning, notation and the first principle","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Derivative (differential coefficient):","bold":true},{"text":" the instantaneous rate of change of y with respect to x. f'(a) is the "},{"text":"slope of the tangent","bold":true},{"text":" to y = f(x) at x = a. Finding it is called "},{"text":"differentiation","bold":true},{"text":"."}]},{"text":[{"text":"Average rate of change","bold":true},{"text":" from x = a to x = b: [f(b) − f(a)]/(b − a) (slope of the chord). "},{"text":"Instantaneous rate","bold":true},{"text":" at x = a: f'(a)."}]},{"text":[{"text":"Change in f:","bold":true},{"text":" f(x + dx) − f(x), found by substituting both values."}]},{"text":[{"text":"First principle:","bold":true},{"text":" f'(x) = lim(h→0) [f(x + h) − f(x)]/h."}]},{"text":[{"text":"Tangent at x = a:","bold":true},{"text":" y − f(a) = f'(a)(x − a)."}]}]},{"type":"table","header":[[{"text":"Notation"}],[{"text":"Name"}],[{"text":"First derivative"}],[{"text":"Second derivative"}]],"rows":[[[{"text":"Ratio of differentials$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 11, $study_guide$"}],[{"text":"Leibniz"}],[{"text":"dy/dx"}],[{"text":"d^2y/dx^2"}]],[[{"text":"Prime"}],[{"text":"Lagrange"}],[{"text":"f'(x), y'"}],[{"text":"f''(x)"}]],[[{"text":"Operator D"}],[{"text":"Euler"}],[{"text":"Df(x), D_x y"}],[{"text":"D^2 f(x)"}]],[[{"text":"Dot over variable"}],[{"text":"Newton"}],[{"text":"y-dot (rate with respect to time)"}],[{"text":"y-double-dot"}]]]},{"type":"paragraph","text":[{"text":"An integral sign, such as integral f(x) dx, is "},{"text":"not","bold":true},{"text":" a derivative notation."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"First principle for f(x) = x^2:","bold":true},{"text":" f(x + h) − f(x) = x^2 + 2xh + h^2 − x^2 = 2xh + h^2. Divide by h: 2x + h. Let h → 0: f'(x) = 2x."}]},{"text":[{"text":"First principle for f(x) = sqrt(x):","bold":true},{"text":" [sqrt(x + h) − sqrt(x)]/h. Multiply top and bottom by sqrt(x + h) + sqrt(x): the top becomes (x + h) − x = h, leaving 1/[sqrt(x + h) + sqrt(x)]. Let h → 0: f'(x) = 1/(2 sqrt(x)). In the same way, sqrt(ax) = sqrt(a)·x^(1/2) gives sqrt(a)/(2 sqrt(x)) = sqrt(ax)/(2x)."}]},{"text":[{"text":"Change in f:","bold":true},{"text":" f(x) = x^2 + 3x, x from 5 to 5.5: f(5.5) = 30.25 + 16.5 = 46.75; f(5) = 40; change = 6.75. For f(x) = x^2 + 8x, x from 6 to 5.5: f(5.5) − f(6) = 74.25 − 84 = −9.75 (negative because x fell)."}]},{"text":[{"text":"Average versus instantaneous:","bold":true},{"text":" f(x) = x^2 + 3x from 1 to 3: [f(3) − f(1)]/(3 − 1) = (18 − 4)/2 = 7. At x = 1, f'(x) = 2x + 3 = 5."}]},{"text":[{"text":"Tangent:","bold":true},{"text":" y = x^2 − 4x + 7 at x = 3: y = 4; slope = 2x − 4 = 2; y − 4 = 2(x − 3), so y = 2x − 2."}]}]}]},{"number":"3.2","title":"Rules of differentiation","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Constant:","bold":true},{"text":" d/dx (k) = 0."}]},{"text":[{"text":"Power:","bold":true},{"text":" d/dx (x^n) = n·x^(n−1), for any real n (negative and fractional too)."}]},{"text":[{"text":"Constant multiple:","bold":true},{"text":" d/dx [k·f(x)] = k·f'(x)."}]},{"text":[{"text":"Sum/difference:","bold":true},{"text":" differentiate term by term."}]},{"text":[{"text":"Product:","bold":true},{"text":" d/dx (uv) = u(dv/dx) + v(du/dx)."}]},{"text":[{"text":"Quotient:","bold":true},{"text":" d/dx (u/v) = [v(du/dx) − u(dv/dx)]/v^2."}]},{"text":[{"text":"Chain (function of a function):","bold":true},{"text":" dy/dx = (dy/du)(du/dx); so d/dx [f(x)]^n = n[f(x)]^(n−1)·f'(x)."}]}]},{"type":"table","header":[[{"text":"Function"}],[{"text":"Derivative"}]],"rows":[[[{"text":"e^x"}],[{"text":"e^x"}]],[[{"text":"e^(mx)"}],[{"text":"m·e^(mx)"}]],[[{"text":"e^(g(x))"}],[{"text":"g'(x)·e^(g(x))"}]],[[{"text":"a^x"}],[{"text":"a^x·ln a"}]],[[{"text":"ln x"}],[{"text":"1/x"}]],[[{"text":"ln g(x)"}],[{"text":"g'(x)/g(x)"}]],[[{"text":"ln(kx), k constant"}],[{"text":"1/x"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Higher derivatives:","bold":true},{"text":" f''(x) is the derivative of f'(x); f'''(x) the derivative of f''(x)."}]},{"text":[{"text":"Differentiating y with respect to z","bold":true},{"text":" (both functions of x): dy/dz = (dy/dx)/(dz/dx)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Rewrite before differentiating.","bold":true},{"text":" 1/x^3 = x^(−3), giving −3x^(−4) = −3/x^4. 1/x^27 gives −27x^(−28). 1/sqrt(x) = x^(−1/2) gives −(1/2)x^(−3/2). 3x^(2/3) gives 2x^(−1/3). x^15·x^(3/2)/x^20 = x^(−7/2), giving −(7/2)x^(−9/2). 3/sqrt(9x) = 1/sqrt(x), so 3/sqrt(9x) + 1/(2x^2) + sqrt(2/5) differentiates to −1/(2 sqrt(x^3)) − 1/x^3 (the constant sqrt(2/5) gives 0)."}]},{"text":[{"text":"Constants stay or vanish:","bold":true},{"text":" y = ax^4 + bx^2 + c gives 4ax^3 + 2bx. y = x^3 − 20x^2 + 3x + 4 gives 3x^2 − 40x + 3."}]},{"text":[{"text":"Expand when easy:","bold":true},{"text":" (x^2 + 1/x)^2 = x^4 + 2x + x^(−2), giving 4x^3 + 2 − 2/x^3. (7x + 3)(4 − 3x) = −21x^2 + 19x + 12, giving 19 − 42x. (1 − x)(1 − 2x)(1 − 3x)(1 − 4x) expands to 24x^4 − 50x^3 + 35x^2 − 10x + 1, giving 96x^3 − 150x^2 + 70x − 10."}]},{"text":[{"text":"Product rule:","bold":true},{"text":" f(x) = (x^2 + 1)(3x − 2) at x = 2. u = x^2 + 1, u' = 2x; v = 3x − 2, v' = 3. f' = 2x(3x − 2) + 3(x^2 + 1) = 2(2)(4) + 3(5) = 31. Also x^2(3x + 1) gives 2x(3x + 1) + 3x^2 = 9x^2 + 2x."}]},{"text":[{"text":"Product with a fractional power:","bold":true},{"text":" x^3(6x − 1)^(2/3) gives 3x^2(6x − 1)^(2/3) + x^3·(2/3)(6x − 1)^(−1/3)·6. Factor out x^2(6x − 1)^(−1/3): x^2[3(6x − 1) + 4x]/(6x − 1)^(1/3) = x^2(22x − 3)/(6x − 1)^(1/3)."}]},{"text":[{"text":"Quotient rule:","bold":true},{"text":" f(x) = (2x + 3)/(x − 1). f' = [2(x − 1) − 1(2x + 3)]/(x − 1)^2 = −5/(x − 1)^2; at x = 3, −5/4 = −1.25. Likewise 5x/(3 − 4x) gives [5(3 − 4x) + 4(5x)]/(3 − 4x)^2 = 15/(3 − 4x)^2; (x^2 + 2x − 21)/(x − 3) gives (x^2 − 6x + 15)/(x − 3)^2; x^2/(3x + 2)^(1/2) gives x(9x + 8)/[2(3x + 2)^(3/2)]."}]},{"text":[{"text":"Chain rule:","bold":true},{"text":" (3x^2 + 4)^100 gives 100(3x^2 + 4)^99·6x = 600x(3x^2 + 4)^99 (never forget the inside derivative 6x). (2x^2 − 3)^4 gives 4(2x^2 − 3)^3·4x; at x = 1: 4(−1)(4) = −16. (2x^2 − 5x − 8)^2 gives 2(2x^2 − 5x − 8)(4x − 5). A term −45(5x^2 + 4)^(−1/2) gives −45·(−1/2)(5x^2 + 4)^(−3/2)·10x = +225x/(5x^2 + 4)^(3/2)."}]},{"text":[{"text":"Chain rule with u:","bold":true},{"text":" y = u + sqrt(u), u = x^3 + 17, at x = 2. u = 25. dy/du = 1 + 1/(2 sqrt(u)) = 1 + 1/10 = 1.1; du/dx = 3x^2 = 12. dy/dx = 1.1 × 12 = 13.2 = 66/5. Similarly y = u/(u + 1), u = 3x^2 − 1, x = 1: u = 2, dy/du = 1/(u + 1)^2 = 1/9, du/dx = 6x = 6, dy/dx = 6/9 = 2/3."}]},{"text":[{"text":"Exponentials and logs:","bold":true},{"text":" 4x^4 + (2x + 1)^3 − (1/4)e^(4x) gives 16x^3 + 6(2x + 1)^2 − e^(4x). e^(x^2 + 2x) gives (2x + 2)e^(x^2 + 2x); e^(ax^2 + bx + c) + ln x gives (2ax + b)e^(ax^2 + bx + c) + 1/x. 3e^(2x) − 4 ln x + 7 gives 6e^(2x) − 4/x. (ln x)^2 gives 2 ln x·(1/x) = 2 ln x/x; (ln x)^5 gives (5/x)(ln x)^4. ln(3x^2 + 1) gives 6x/($study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 12, $study_guide$3x^2 + 1) = 6/4 = 1.50 at x = 1. 2^x gives 2^x ln 2 = 8 × 0.6931 = 5.55 at x = 3 (2 d.p.)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" d/dx [ln(5x)] = 5/(5x) = 1/x, "},{"text":"not","bold":true},{"text":" 5/x."}]},{"text":[{"text":"Investment growth:","bold":true},{"text":" V(t) = 20,000e^(0.08t). V'(t) = 1,600e^(0.08t); at t = 5: 1,600e^(0.4) = 1,600 × 1.491825 = ₦2,386.92 per year (2 d.p.)."}]},{"text":[{"text":"Higher derivatives:","bold":true},{"text":" f(x) = 5x^7 + 3x^3 − 2x^2 + 10: f' = 35x^6 + 9x^2 − 4x; f'' = 210x^5 + 18x − 4; f''' = 1050x^4 + 18. f(x) = 2x^4 − 3x^2 + 5x: f'' = 24x^2 − 6, so f''(1) = 18."}]},{"text":[{"text":"With respect to another function:","bold":true},{"text":" x^5 with respect to x^2: 5x^4/(2x) = (5/2)x^3. ln x with respect to x^2: (1/x)/(2x) = 1/(2x^2)."}]},{"text":[{"text":"Log laws first:","bold":true},{"text":" ln[e^x((x − 1)/(x + 1))^(3/2)] = x + (3/2)ln(x − 1) − (3/2)ln(x + 1). Derivative: 1 + (3/2)[1/(x − 1) − 1/(x + 1)] = 1 + 3/(x^2 − 1) = (x^2 + 2)/(x^2 − 1). Also ln(sqrt(x + 1) − sqrt(x − 1)) differentiates to −1/(2 sqrt(x^2 − 1)) for x > 1."}]}]}]},{"number":"3.3","title":"Implicit and logarithmic differentiation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Implicit differentiation:","bold":true},{"text":" when y is not made the subject, differentiate every term with respect to x, writing d/dx (y^n) = n·y^(n−1)·(dy/dx) and using the product rule on terms like xy; then collect dy/dx."}]},{"text":[{"text":"Partial-derivative shortcut:","bold":true},{"text":" for f(x, y) = 0, dy/dx = −fx/fy, where fx treats y as constant and fy treats x as constant."}]},{"text":[{"text":"Logarithmic differentiation","bold":true},{"text":" (for u^v, a variable raised to a variable power): take ln of both sides, ln y = v·ln u; differentiate: (1/y)(dy/dx) = v'·ln u + v·u'/u; multiply by y."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"x^2 + y − 2x = 0:","bold":true},{"text":" 2x + dy/dx − 2 = 0, so dy/dx = 2 − 2x. By partials: fx = 2x − 2, fy = 1, dy/dx = −(2x − 2)/1 = 2 − 2x."}]},{"text":[{"text":"x^2 − y^2 + 3x = 5y:","bold":true},{"text":" 2x − 2y(dy/dx) + 3 = 5(dy/dx), so (2x + 3) = (5 + 2y)(dy/dx), giving dy/dx = (2x + 3)/(2y + 5)."}]},{"text":[{"text":"2x^2 + 3x + y^2 = 0:","bold":true},{"text":" 4x + 3 + 2y(dy/dx) = 0, so dy/dx = −(4x + 3)/(2y). "},{"text":"5x^3 − 3x^2 + 3y^2 − 6 = 7:","bold":true},{"text":" 15x^2 − 6x + 6y(dy/dx) = 0, so dy/dx = x(2 − 5x)/(2y)."}]},{"text":[{"text":"Cross terms:","bold":true},{"text":" x^2 + 2hxy + y^2 = 0: fx = 2x + 2hy, fy = 2hx + 2y, so dy/dx = −(x + hy)/(hx + y). ax^2 + 2mxy + by^2 = k gives −(ax + my)/(mx + by). x^3 + 3bxy + y^3 = b^4 gives −(x^2 + by)/(bx + y^2)."}]},{"text":[{"text":"ln(xy) = x^2 + y^2:","bold":true},{"text":" ln x + ln y = x^2 + y^2, so 1/x + (1/y)(dy/dx) = 2x + 2y(dy/dx). Collect: (dy/dx)(1/y − 2y) = 2x − 1/x, giving dy/dx = y(2x^2 − 1)/[x(1 − 2y^2)]."}]},{"text":[{"text":"e^(xy) − 4xy = 2:","bold":true},{"text":" e^(xy)(y + x·dy/dx) − 4(y + x·dy/dx) = 0, so (e^(xy) − 4)(y + x·dy/dx) = 0, giving dy/dx = −y/x."}]},{"text":[{"text":"(2x)^(5x + 2):","bold":true},{"text":" ln y = (5x + 2)ln(2x). (1/y)y' = 5 ln(2x) + (5x + 2)(2/(2x)) = 5 ln(2x) + (5x + 2)/x. So y' = (2x)^(5x + 2)[(5x + 2)/x + 5 ln(2x)]."}]},{"text":[{"text":"(1 + x)^(2x):","bold":true},{"text":" ln y = 2x ln(1 + x); y'/y = 2 ln(1 + x) + 2x/(1 + x); y' = 2(1 + x)^(2x)[x/(1 + x) + ln(1 + x)]."}]},{"text":[{"text":"x^(ln x):","bold":true},{"text":" ln y = (ln x)^2; y'/y = 2 ln x/x; y' = 2x^(ln x − 1)·ln x."}]},{"text":[{"text":"(12x^2 + 6)^(5x + 2):","bold":true},{"text":" y'/y = 5 ln(12x^2 + 6) + (5x + 2)(24x)/(12x^2 + 6), and 24x/(12x^2 + 6) = 4x/(2x^2 + 1)."}]},{"text":[{"text":"x^(x^x):","bold":true},{"text":" ln y = x^x ln x. Since d/dx (x^x) = x^x(1 + ln x), y'/y = x^x(1 + ln x)ln x + x^x/x, so y' = x^(x^x)[x^x ln x(1 + ln x) + x^(x − 1)]."}]},{"text":[{"text":"Trap:","bold":true},{"text":" d/dx (2x)^(5x + 2) is not 2(5x + 2)(2x)^(5x + 1); the power rule only works when the exponent is constant."}]}]}]},{"number":"3.4","title":"Rates of change, percentage rates and approximation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Rate of change","bold":true},{"text":" of Q with respect to t: Q'(t)."}]},{"text":[{"text":"Percentage rate of change:","bold":true},{"text":" 100·f'(x)/f(x)."}]},{"text":[{"text":"Approximation:","bold":true},{"text":" Δf ≈ f'(x)·Δx. "},{"text":"Percentage change","bold":true},{"text":" ≈ 100·f'(x)Δx/f(x)."}]},{"text":[{"text":"Actual change","bold":true},{"text":" over an interval: f(new) − f(old). \"During the 16th month\" means from x = 15 to x = 16; \"during the 6th year\" means t = 5 to t = 6."}]},{"text":[{"text":"Input needed","bold":true},{"text":" for a target output change: ΔL ≈ ΔQ/Q'(L)."}]},{"text":[{"text":"Time variable:","bold":true},{"text":" t counts years from the base year; \"in 1991\" with base 1987 means t = 4. Ten minutes = 1/6 hour; 6 months = 0.5 year; a quarter = 0.25 year."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Population:","bold":true},{"text":" P(x) = x^2 + 20x + 8,000. P'(x) = 2x + 20; at x = 15: 50 people per month. Actual change in the 16th month: P(16) − P(15) = 8,576 − 8,525 = 51 people."}]},{"text":[{"text":"Newspaper:","bold":true},{"text":" C(t) = 100t^2 + 400t + 5,000. C'(t) = 200t + 400; at t = 5: 1,400 per year. Actual change in the 6th year: C(6) − C(5) = 11,000 − 9,500 = 1,500. Next 6 months from now: C'(0) × 0.5 = 400 × 0.5 = 200."}]},{"text":[{"text":"Worker output:","bold":true},{"text":" f(x) = −x^3 + 6x^2 + 15x radios, from 8:00 a.m. At 9:00 (x = 1): f'(x) = −3x^2 + 12x + 15 = 24 per hour. Actual between 9 and 10: f(2) − f(1) = 46 − 20 = 26. For Q(t) = −t^3 + 6t^2 + 24t at 11:00 (t = 3): Q' = −27 + 36 + 24 = 33 units per hour. Change in that rate from 11:00 to 11:10: Q''(t) = −6t + 12 = −6; × 1/6 hour = −1, a decrease of about 1 unit per h$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 13, $study_guide$our."}]},{"text":[{"text":"Percentage rate:","bold":true},{"text":" GNP N(t) = t^2 + 5t + 106 (₦ billion, t after 1980). In 1988, t = 8: N' = 2(8) + 5 = 21; N = 210; 100 × 21/210 = 10% per year. For f(x) = x(x + 3)^2 at x = 3: f' = (x + 3)^2 + 2x(x + 3) = 72, f = 108, rate = 66.67%."}]},{"text":[{"text":"Earnings:","bold":true},{"text":" A(t) = 0.1t^2 + 10t + 20 (₦ thousand, formed 1987). In 1991, t = 4: A' = 0.2(4) + 10 = 10.8, i.e. ₦10,800 per year; A = 61.6; percentage = 100 × 10.8/61.6 = 17.53% (2 d.p.). For f(t) = sqrt(10t^2 + t + 236) in January 1992 (t = 4): f = sqrt(400) = 20; f' = (20t + 1)/(2f) = 81/40 = 2.025, i.e. ₦2,025 per year; percentage = 100 × 2.025/20 = 10.125%."}]},{"text":[{"text":"Long run:","bold":true},{"text":" P(t) = t^2 + 200t + 10,000 = (t + 100)^2. Percentage rate = 100 × 2(t + 100)/(t + 100)^2 = 200/(t + 100)%, which approaches 0 as t grows."}]},{"text":[{"text":"Linear growth:","bold":true},{"text":" GNP ₦125 billion (1986), ₦155 billion (1988): it rises ₦15 billion per year. In 1991 GNP = 125 + 5(15) = 200; percentage rate = 100 × 15/200 = 7.5%."}]},{"text":[{"text":"Estimating a change:","bold":true},{"text":" f(x) = x^2 − 3x + 5, x from 5 to 5.3: f'(5) = 7; Δf ≈ 7 × 0.3 = 2.1. Cost C(q) = 3q^2 + 5q + 10, q from 40 to 40.5: C'(40) = 245; ΔC ≈ 245 × 0.5 = ₦122.50. C(q) = 0.1q^3 − 0.5q^2 + 500q + 200, q from 4 to 4.1: C'(4) = 4.8 − 4 + 500 = 500.8; ΔC ≈ ₦50.08. Carbon monoxide Q(t) = 0.05t^2 + 0.1t + 3.4 over the coming 6 months: Q'(0) × 0.5 = 0.05 ppm."}]},{"text":[{"text":"Percentage change:","bold":true},{"text":" GNP N(t) = t^2 + 5t + 200 (base 1990), first quarter of 1998: t = 8, Δt = 0.25. N'(8) = 21, N(8) = 304. ΔN ≈ 5.25; 100 × 5.25/304 = 1.73%. Property tax T(x) = 60x^(3/2) + 40x + 1,200 (base 1988), first half of 1992: x = 4, Δx = 0.5; T' = 90x^(1/2) + 40 = 220; ΔT ≈ 110; T(4) = 1,840; 100 × 110/1,840 = 5.98%, about 6%."}]},{"text":[{"text":"Capital:","bold":true},{"text":" Q(k) = 600k^(1/2) with k in ₦1,000 units, k = 900 (₦900,000), extra ₦800 means Δk = 0.8. Q'(900) = 300/30 = 10; ΔQ ≈ 8 units."}]},{"text":[{"text":"1% rise in input:","bold":true},{"text":" Q = 4,000K^(1/2). ΔK = 0.01K; ΔQ ≈ 2,000K^(−1/2) × 0.01K = 20K^(1/2); percentage = 100 × 20K^(1/2)/(4,000K^(1/2)) = 0.5%. Rule: if Q = A·K^n, a 1% rise in K raises Q by about n%. So 400K^(1/2) also gives 0.5%."}]},{"text":[{"text":"Labour needed:","bold":true},{"text":" Q(L) = 900L^(1/3), L = 1,000. Q' = 300L^(−2/3) = 300/100 = 3; ΔL ≈ 15/3 = 5 worker-hours. Q(L) = 300L^(2/3), L = 512: Q' = 200L^(−1/3) = 200/8 = 25; ΔL ≈ 12.5/25 = 0.5 worker-hour."}]},{"text":[{"text":"Chain rule in context:","bold":true},{"text":" carbon monoxide C(p) = sqrt(0.5p^2 + 17), p(t) = 3.1 + 0.1t^2. At t = 3, p = 4. dC/dp = 0.5p/sqrt(0.5p^2 + 17) = 2/5 = 0.4; dp/dt = 0.2t = 0.6; dC/dt = 0.4 × 0.6 = 0.24 ppm per year."}]}]}]},{"number":"3.5","title":"Marginal analysis","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marginal cost (MC):","bold":true},{"text":" MC = C'(x) = dTC/dx, the rate of change of total cost; approximately the cost of the "},{"text":"(x + 1)th","bold":true},{"text":" unit."}]},{"text":[{"text":"Actual cost of the nth unit:","bold":true},{"text":" C(n) − C(n − 1)."}]},{"text":[{"text":"Marginal revenue (MR):","bold":true},{"text":" MR = R'(x); TR = p·x. "},{"text":"Average revenue:","bold":true},{"text":" AR = R/x = p."}]},{"text":[{"text":"Marginal profit:","bold":true},{"text":" P'(x) = MR − MC, where P(x) = R(x) − C(x)."}]},{"text":[{"text":"Average cost:","bold":true},{"text":" AC = C(x)/x. "},{"text":"Total cost from AC:","bold":true},{"text":" C = AC·x, then MC = dC/dx."}]},{"text":[{"text":"Marginal average cost:","bold":true},{"text":" MAC = d(AC)/dx. "},{"text":"Rate of change of MC:","bold":true},{"text":" C''(x)."}]},{"text":[{"text":"MC and AC:","bold":true},{"text":" MC < AC means AC falling; MC > AC means AC rising; MC = AC at minimum AC."}]},{"text":[{"text":"Minimum AC:","bold":true},{"text":" solve d(AC)/dx = 0 and check d^2(AC)/dx^2 > 0."}]},{"text":[{"text":"MR = 0","bold":true},{"text":" gives the output of maximum total revenue; "},{"text":"MR = MC","bold":true},{"text":" gives the profit-maximising output."}]},{"text":[{"text":"Marginal propensity to consume:","bold":true},{"text":" MPC = dC/dY. "},{"text":"Savings","bold":true},{"text":" S = Y − C; "},{"text":"MPS","bold":true},{"text":" = dS/dY = 1 − MPC."}]},{"text":[{"text":"C''(x) > 0:","bold":true},{"text":" MC rising; "},{"text":"C''(x) < 0:","bold":true},{"text":" MC falling."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Interpreting MC:","bold":true},{"text":" C(x) = 10,000 + 30x + 0.02x^2. MC = 30 + 0.04x; at 200: ₦38 per unit. This means raising output from 200 to 201 adds "},{"text":"about","bold":true},{"text":" ₦38. The actual 201st unit costs C(201) − C(200) = 16,838.02 − 16,800 = ₦38.02."}]},{"text":[{"text":"More MC values:","bold":true},{"text":" 25,000 + 40x + 0.05x^2 at 300: 40 + 0.1(300) = ₦70. 0.01x^3 − 0.6x^2 + 50x + 8,000 at 30: 0.03(900) − 1.2(30) + 50 = ₦41. 1,000 + 25x + 2x^2 at 15: 25 + 60 = 85. 2x^2 + 3x + 4 at 5: 23. Oil C = 50 + 1.5x + 0.02x^2: MC = 1.5 + 0.04x, ₦1.70 at x = 5, ₦3.10 at x = 40. Pencils 30 + 1.5x + 0.0008x^2 at 1,000: ₦3.10. Pens C(p) = 0.0015p^3 − 0.9p^2 + 200p + 60,000: MC = 0.0045p^2 − 1.8p + 200 = ₦65, ₦20, ₦65 at 100, 200, 300."}]},{"text":[{"text":"Estimate versus actual:","bold":true},{"text":" C = (1/8)x^2 + 3x + 98. The 9th unit is estimated by C'(8) = (1/4)(8) + 3 = ₦5.00; actual C(9) − C(8) = 135.125 − 130 = ₦5.125. C = 1,000 + 25x + 2x^2: actual 15th unit = C(15) − C(14) = 1,825 − 1,742 = 83. C(q) = q^3 − 30q^2 + 400q + 500: 20th unit = C(20) − C(19) = 4,500 − 4,129 = ₦371. C(q) = q^3 − 6q^2 + 20q + 400: MC at 10 = 300 − 120 + 20 = ₦200; 11th unit = 1,225 − 1,000 = ₦225."}]},{"text":[{"text":"MR from demand:","bold":true},{"text":" always form TR = p × quantity first. P = 60 − Q: TR = 60Q − Q^2, MR = 60 − 2Q = $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 14, $study_guide$−40 at Q = 50; the actual change from 50 to 51 is TR(51) − TR(50) = 459 − 500 = −41. P = 100 − 4Q: MR = 100 − 8Q = 4 at Q = 12, so a 0.3 rise changes TR by about 4 × 0.3 = 1.2. p = 800 − 4x: MR = 800 − 8x = ₦320 at 60. p = 1,500 − 2x − x^2: TR = 1,500x − 2x^2 − x^3, MR = 1,500 − 4x − 3x^2 = 220 at 20. p = 30 + 2x − 5x^2: MR = 30 + 4x − 15x^2 = −93 at 3. R(x) = 12x + 2x^2 + 6: MR = 12 + 4x = 212 at 50; actual 51st item = R(51) − R(50) = 214. p = (1/3)(75 − x): R = 25x − x^2/3, R'(8) = 25 − 16/3 = ₦19.67 estimates the 9th unit; actual R(9) − R(8) = 198 − 178.67 = ₦19.33."}]},{"text":[{"text":"Make price the subject first:","bold":true},{"text":" Q = 400 − 2P gives P = 200 − 0.5Q; TR = 200Q − 0.5Q^2; MR = 200 − Q = ₦80 at Q = 120. x = 100 − 4p gives p = 25 − x/4; MR = 25 − x/2 = 0 at x = 50, so p = ₦12.50."}]},{"text":[{"text":"Linear demand from two points:","bold":true},{"text":" p = ax + b, selling 1,250 at ₦5 and 1,500 at ₦4. a = (4 − 5)/(1,500 − 1,250) = −1/250; 5 = −5 + b, b = 10. p = 10 − x/250; TR = 10x − x^2/250; MR = 10 − x/125. MR = 0 at x = 1,250, price ₦5. For 1,000 at ₦4 and 1,500 at ₦2: a = −1/250, b = 8, MR = 8 − x/125."}]},{"text":[{"text":"MC from AC:","bold":true},{"text":" AC = 100/Q + 2 gives TC = 100 + 2Q, MC = 2. Radios AC = x^2 − 10x + 30 (₦ hundred): C = x^3 − 10x^2 + 30x, MC = 3x^2 − 20x + 30 = 18 at x = 6, i.e. ₦1,800. AC = 0.006x^2 − 0.02x − 30 + 5,000/x: C = 0.006x^3 − 0.02x^2 − 30x + 5,000, MC = 0.018x^2 − 0.04x − 30 = 45 − 2 − 30 = 13 at 50. AC = x + 5 + 36/x: C = x^2 + 5x + 36, MC = 2x + 5 = 25 at 10."}]},{"text":[{"text":"AC and MC at a point:","bold":true},{"text":" C = 2x^2 + x − 5 at x = 4: AC = 31/4 = 7.75; MC = 4x + 1 = 17. C = 3,200 + 25x + 0.5x^2 at 50: MC = 25 + x = ₦75; AC = 64 + 25 + 25 = ₦114. MC < AC, so AC is "},{"text":"falling","bold":true},{"text":"."}]},{"text":[{"text":"When is AC rising?","bold":true},{"text":" AC = x + 5 + 36/x: d(AC)/dx = 1 − 36/x^2 > 0 when x > 6."}]},{"text":[{"text":"MAC and C'':","bold":true},{"text":" C = 0.002x^3 − 0.04x^2 + 5x + 1,500: AC = 0.002x^2 − 0.04x + 5 + 1,500/x; MAC = 0.004x − 0.04 − 1,500/x^2. MC = 0.006x^2 − 0.08x + 5; rate of change of MC = 0.012x − 0.08. For C = 0.02x^3 − 3x^2 + 200x + 5,000: C'' = 0.12x − 6 = −1.2 at 40, so MC is falling by about ₦1.20 per extra unit."}]},{"text":[{"text":"MC = AC:","bold":true},{"text":" C = (3/4)x^2 − 7x + 27. MC = 1.5x − 7; AC = 0.75x − 7 + 27/x. Equate: 0.75x = 27/x, x^2 = 36, x = 6."}]},{"text":[{"text":"Minimum AC:","bold":true},{"text":" C = 1,800 + 10x + 2x^2. AC = 1,800/x + 10 + 2x. d(AC)/dx = −1,800/x^2 + 2 = 0, so x = 30. d^2(AC)/dx^2 = 3,600/x^3 > 0, a minimum. AC = 60 + 10 + 60 = ₦130 per unit."}]},{"text":[{"text":"Marginal profit:","bold":true},{"text":" R = 120x − 0.5x^2, C = 2,000 + 40x + 0.3x^2. MR = 120 − x = 90; MC = 40 + 0.6x = 58 at x = 30. Marginal profit = ₦32."}]},{"text":[{"text":"MR = MC:","bold":true},{"text":" pencils sold at ₦5 each, so MR = 5. 1.5 + 0.0016x = 5 gives x = 2,187.5. C = 50x + 30,000 and p = 100 − 0.01x: MC = 50, MR = 100 − 0.02x; 100 − 0.02x = 50 gives x = 2,500."}]},{"text":[{"text":"MPC and MPS:","bold":true},{"text":" C = 40 + 0.7Y + 2 sqrt(Y): MPC = 0.7 + 1/sqrt(Y) = 0.7 + 0.1 = 0.80 at Y = 100. C = 150 + 0.9Y − 0.0002Y^2: MPC = 0.9 − 0.0004Y = 0.7 at Y = 500, so MPS = 1 − 0.7 = 0.30."}]}]}]},{"number":"3.6","title":"Elasticity","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Price elasticity of demand (point):","bold":true},{"text":" eta = −(p/q)(dq/dp), a positive number. Some questions use the signed form E = (p/q)(dq/dp), which is negative for normal demand."}]},{"text":[{"text":"Meaning:","bold":true},{"text":" a 1% rise in price cuts quantity demanded by about eta%. % change in quantity ≈ eta × % change in price."}]}]},{"type":"table","header":[[{"text":"Value of eta"}],[{"text":"Demand"}],[{"text":"Raising price makes TR"}]],"rows":[[[{"text":"eta > 1"}],[{"text":"Elastic"}],[{"text":"fall"}]],[[{"text":"eta < 1"}],[{"text":"Inelastic"}],[{"text":"rise"}]],[[{"text":"eta = 1"}],[{"text":"Unit elastic"}],[{"text":"stay about the same (TR is at its maximum)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"With the signed form E, unit elasticity means E = −1."}]},{"text":[{"text":"Inverse demand","bold":true},{"text":" (P in terms of Q): dQ/dP = 1/(dP/dQ)."}]},{"text":[{"text":"Constant elasticity:","bold":true},{"text":" Q = A/P^n gives eta = n at every price."}]},{"text":[{"text":"Elasticity of total cost with respect to output:","bold":true},{"text":" (dTC/dq)/(TC/q) = MC/AC."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"q = 240 − 2p at p = 100:","bold":true},{"text":" q = 40; dq/dp = −2; eta = (100/40)(2) = 5. Elastic: a 1% price rise cuts demand by about 5%. Unit elasticity: 2p/(240 − 2p) = 1 gives 4p = 240, p = 60."}]},{"text":[{"text":"q = 300 − p^2:","bold":true},{"text":" eta = (p/(300 − p^2))(2p) = 2p^2/(300 − p^2). eta = 1 when 3p^2 = 300, p = 10. Inelastic for 0 ≤ p < 10, elastic for p > 10. TR = 300p − p^3, TR' = 300 − 3p^2 = 0 at p = 10: total revenue is "},{"text":"greatest","bold":true},{"text":" at unit elasticity."}]},{"text":[{"text":"Signed form:","bold":true},{"text":" q = p/(p − 5), p > 5. dq/dp = [(p − 5) − p]/(p − 5)^2 = −5/(p − 5)^2. E = (p/q)(dq/dp) = (p − 5)·(−5)/(p − 5)^2 = −5/(p − 5) = 5/(5 − p). At p = 7: −2.5. Unit elastic: 5/(5 − p) = −1 gives p = 10."}]},{"text":[{"text":"Inverse demand:","bold":true},{"text":" P = 100 − 2Q at Q = 20: P = 60; dP/dQ = −2, so dQ/dP = −1/2. eta = (60/20)(1/2) = 1.5, elastic."}]},{"text":[{"text":"Constant elasticity:","bold":true},{"text":" Q = 2,000/P^2 = 2,000P^(−2); dQ/dP = −4,000P^(−3); eta = (P/(2,000P^(−2)))(4,000P^(−3)) = 2, elastic at every price."}]},{"text":[{"text":"Estimating a fall in demand:","bold":true},{"text":" Q = 500 − 5P at P = ₦60: Q = 200; eta = (60/200)(5) = 1.5. A 2% price rise cuts Q by about 1.5 × 2 = 3%."}]},{"text":[{"text":"Trap:","bold":true},{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 15, $study_guide$" elasticity of cost divides MC "},{"text":"by","bold":true},{"text":" AC; it is not MC × AC, and it uses TC, not TR."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Notations: dy/dx Leibniz, f'(x) Lagrange, Df(x) Euler, y-dot Newton; f'(a) is the slope of the tangent."}]},{"text":[{"text":"First principle: f'(x) = lim(h→0) [f(x + h) − f(x)]/h."}]},{"text":[{"text":"Power, product u·v' + v·u', quotient (v·u' − u·v')/v^2, chain (dy/du)(du/dx); d/dx e^(mx) = m·e^(mx), d/dx ln g = g'/g, d/dx a^x = a^x ln a."}]},{"text":[{"text":"Implicit: dy/dx = −fx/fy; u^v needs logarithmic differentiation."}]},{"text":[{"text":"Percentage rate = 100·f'/f; Δf ≈ f'(x)Δx; actual nth unit = f(n) − f(n − 1)."}]},{"text":[{"text":"MC = C', MR = R' (form TR = p·x first), marginal profit = MR − MC, MC from AC via C = AC·x."}]},{"text":[{"text":"MC = AC at minimum AC; MR = 0 maximises TR; MR = MC maximises profit; MPS = 1 − MPC."}]},{"text":[{"text":"eta = −(p/q)(dq/dp): above 1 elastic, below 1 inelastic, equal to 1 maximises TR; elasticity of cost = MC/AC."}]}]}],"theory":{"itemId":"b0c82034-aee8-554d-9d28-7486f0bf2628","question":[{"type":"paragraph","text":[{"text":"A bakery in Yaba has total cost C(x) = 0.5x^2 + 20x + 800 naira for x loaves. Find (a) MC at x = 40, (b) the actual cost of the 41st loaf, (c) AC at x = 40, and (d) the output that minimises AC."}]}]},"practice":[{"topic":"Differentiation and Marginal Analysis","named":false}]}},{"kind":"note","itemId":"6b46841a-d7e2-55a6-b1a1-a8858278896a","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Optimisation and Growth Models","body":"Stationary points, the first- and second-derivative tests, concavity and inflection; minimising cost and maximising revenue and profit; monopoly, price discrimination and Cournot duopoly; partial derivatives and marginal analysis with two variables; unconstrained and Lagrange (constrained) optimisation; exponential growth and decay models.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"Stationary points, the first- and second-derivative tests, concavity and inflection; minimising cost and maximising revenue and profit; monopoly, price discrimination and Cournot duopoly; partial derivatives and marginal analysis with two variables; unconstrained and Lagrange (constrained) optimisation; exponential growth and decay models."}],"lessons":[{"number":"4.1","title":"Stationary points, maxima, minima and inflection","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Rules you need:","bold":true},{"text":" d/dx (k) = 0; d/dx (x^n) = n·x^(n−1); d/dx (k·f) = k·f′; sum rule (differentiate term by term); product (uv)′ = u′v + uv′; quotient (u/v)′ = (v·u′ − u·v′)/v^2; chain d/dx f(g(x)) = f′(g(x))·g′(x); d/dx e^(kx) = k·e^(kx); d/dx ln x = 1/x; d/dx sqrt(u) = u′/(2 sqrt(u))."}]},{"text":[{"text":"Stationary (critical) point:","bold":true},{"text":" where f′(x) = 0. Maxima and minima are called turning points."}]},{"text":[{"text":"Second-derivative test","bold":true},{"text":" at f′(a) = 0:"}]}]},{"type":"table","header":[[{"text":"f″(a)"}],[{"text":"Conclusion"}]],"rows":[[[{"text":"f″(a) < 0"}],[{"text":"relative (local) maximum"}]],[[{"text":"f″(a) > 0"}],[{"text":"relative (local) minimum"}]],[[{"text":"f″(a) = 0"}],[{"text":"inconclusive: use the first-derivative test"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"First-derivative test:","bold":true},{"text":" f′ changes + to − = maximum; − to + = minimum; no sign change = neither (a stationary point of inflection)."}]},{"text":[{"text":"Concavity:","bold":true},{"text":" f″ > 0 concave upward; f″ < 0 concave downward. "},{"text":"Point of inflection:","bold":true},{"text":" where concavity changes (f″ = 0 or undefined and changes sign)."}]},{"text":[{"text":"Point of diminishing returns:","bold":true},{"text":" the inflection point of a sales or output function; after it, each extra naira adds less."}]},{"text":[{"text":"Maximum/minimum value","bold":true},{"text":" = f(a), found by putting a back into the original f."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Example (f(x) = x^3 − 9x^2 + 24x − 12):","bold":true},{"text":" f′(x) = 3x^2 − 18x + 24 = 3(x − 2)(x − 4) = 0, so x = 2 or 4. f″(x) = 6x − 18. f″(2) = −6 < 0: maximum, f(2) = 8 − 36 + 48 − 12 = 8. f″(4) = 6 > 0: minimum, f(4) = 64 − 144 + 96 − 12 = 4."}]},{"text":[{"text":"Constants:","bold":true},{"text":" for 15x^4 + 8x^3 − 18x^2 (maximum value 0 at x = 0; minima −11 at x = −1 and −2.808 at x = 3/5), adding +1 shifts every value up by 1 (1, −10, −1.808) but not the x-values."}]},{"text":[{"text":"When f″ = 0 (f(x) = (8/3)x^3 − x^4):","bold":true},{"text":" f′ = 8x^2 − 4x^3 = 4x^2(2 − x) = 0 at x = 0, 2. f″ = 16x − 12x^2; f″(2) = −16: maximum at (2, 64/3 − 16) = (2, 16/3). f″(0) = 0, and f′ is positive on both sides of 0, so x = 0 is neither a maximum nor a minimum."}]},{"text":[{"text":"Inflection (f(x) = x^3 − (3/2)x^2 + 5):","bold":true},{"text":" f″ = 6x − 3 = 0 at x = 1/2. f″ < 0 for x < 1/2 (concave downward), > 0 for x > 1/2 (concave upward). f(1/2) = 1/8 − 3/8 + 5 = 19/4. Point of inflection (1/2, 19/4)."}]},{"text":[{"text":"Diminishing returns:","bold":true},{"text":" a tyre dealer's sales S(x) = −0.02x^3 + 3x^2 + 100 (both in ₦ thousands). S″ = −0.12x + 6 = 0 gives x = 50. S(50) = −2,500 + 7,500 + 100 = 5,100. So ₦50,000 on advertising, sales ₦5,100,000."}]}]}]},{"number":"4.2","title":"Optimising cost, revenue and profit","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Definitions:","bold":true},{"text":" TR = R = p·x (write p from the demand equation first); MR = dR/dx; MC = dC/dx; AC = C/x; profit P = R − C."}]},{"text":[{"text":"Conditions:","bold":true}]}]},{"type":"table","header":[[{"text":"Goal"}],[{"text":"First-order condition"}],[{"text":"Second-order condition"}]],"rows":[[[{"text":"Minimum MC"}],[{"text":"d(MC)/dx = 0"}],[{"text":"d^2(MC)/dx^2 > 0"}]],[[{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 16, $study_guide$xt":"Minimum AC"}],[{"text":"d(AC)/dx = 0"}],[{"text":"d^2(AC)/dx^2 > 0"}]],[[{"text":"Maximum revenue"}],[{"text":"MR = 0"}],[{"text":"R″ < 0"}]],[[{"text":"Maximum profit"}],[{"text":"P′ = 0, i.e. "},{"text":"MR = MC","bold":true}],[{"text":"P″ < 0"}]],[[{"text":"Minimum total cost"}],[{"text":"C′ = 0"}],[{"text":"C″ > 0"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"MC = AC at minimum AC:","bold":true},{"text":" AC falls while MC < AC, rises while MC > AC."}]},{"text":[{"text":"MR = MC holds where total profit is at its maximum","bold":true},{"text":" (not where TR = TC, which is break-even)."}]},{"text":[{"text":"Quadratic shortcut:","bold":true},{"text":" y = ax^2 + bx + c has its turning point at x = −b/(2a) (maximum if a < 0)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost (C = 300x − 10x^2 + (1/3)x^3):","bold":true},{"text":" MC = x^2 − 20x + 300; d(MC)/dx = 2x − 20 = 0 gives "},{"text":"x = 10","bold":true},{"text":" (minimum MC, second derivative 2 > 0). AC = C/x = (1/3)x^2 − 10x + 300; d(AC)/dx = (2/3)x − 10 = 0 gives "},{"text":"x = 15","bold":true},{"text":" (minimum AC). AC = MC: (1/3)x^2 − 10x + 300 = x^2 − 20x + 300, so 10x = (2/3)x^2, giving x = 15 or x = 0. Reject x = 0, because average cost C/x is undefined at zero output, so the answer is "},{"text":"x = 15","bold":true},{"text":"."}]},{"text":[{"text":"Overheads (₦6,000 overheads, ₦5 per unit material, labour x^2/60):","bold":true},{"text":" C = 6,000 + 5x + x^2/60; AC = 6,000/x + 5 + x/60. d(AC)/dx = −6,000/x^2 + 1/60 = 0, x^2 = 360,000, "},{"text":"x = 600","bold":true},{"text":"; AC = 10 + 5 + 10 = "},{"text":"₦25","bold":true},{"text":"."}]},{"text":[{"text":"Minimum total cost (C = x^3 − 195x^2 + 6,600x + 15,000):","bold":true},{"text":" C′ = 3x^2 − 390x + 6,600 = 3(x − 20)(x − 110) = 0. C″ = 6x − 390: C″(110) = 270 > 0, so "},{"text":"110","bold":true},{"text":" is the minimum (x = 20 is a maximum)."}]},{"text":[{"text":"Revenue from demand:","bold":true},{"text":" p = (80 − x)/4, so R = (80x − x^2)/4; MR = 20 − x/2 = 0, "},{"text":"x = 40","bold":true},{"text":", R = (3,200 − 1,600)/4 = "},{"text":"₦400","bold":true},{"text":". If x is given in terms of p, rewrite p first (x = 70 − 5p: p = 14 − x/5), or maximise R = p·x in p (x = 100 − 5p: R = 100p − 5p^2, p = ₦10). For Q = 40 − P: R = 40Q − Q^2, MR = 40 − 2Q = 0, so revenue is maximised at "},{"text":"Q = 20","bold":true},{"text":"; at a set price of ₦15, Q = 25, R = ₦375."}]},{"text":[{"text":"Bulk-discount orders:","bold":true},{"text":" ₦700 per set up to 60 sets, ₦10 less per set for each set above 60. For x > 60, price = 700 − 10(x − 60) = 1,300 − 10x; R = 1,300x − 10x^2; R′ = 1,300 − 20x = 0, "},{"text":"x = 65 sets","bold":true},{"text":"."}]},{"text":[{"text":"Profit (R = 600y − 8y^2, C = y^2 + 78y + 2,500):","bold":true},{"text":" P = 522y − 9y^2 − 2,500; P′ = 522 − 18y = 0, "},{"text":"y = 29","bold":true},{"text":". If P′ = 0 has two roots, keep the one with P″ < 0."}]},{"text":[{"text":"Profit as a function of price:","bold":true},{"text":" lamps sell 3,000 at ₦6, 1,000 fewer per ₦1 rise, cost ₦4. Quantity = 3,000 − 1,000(x − 6) = 9,000 − 1,000x. P = (x − 4)(9,000 − 1,000x). P′ = (9,000 − 1,000x) − 1,000(x − 4) = 13,000 − 2,000x = 0, "},{"text":"x = ₦6.50","bold":true},{"text":". In general P = (x − c)(a − x) peaks at x = (a + c)/2: (80 + 10)/2 = ₦45; (120 + 20)/2 = ₦70; 400(15 − x)(x − 2) peaks at (15 + 2)/2 = ₦8.50."}]},{"text":[{"text":"Quotient rule profit:","bold":true},{"text":" P = 8,000x/(500 + x) − x. P′ = 8,000·500/(500 + x)^2 − 1 = 0, so (500 + x)^2 = 4,000,000, 500 + x = 2,000, "},{"text":"x = 1,500","bold":true},{"text":"; P = 6,000 − 1,500 = "},{"text":"4,500","bold":true},{"text":"."}]},{"text":[{"text":"Root demand:","bold":true},{"text":" q = 8,100/p^2 gives p = 90/sqrt(q). R = 90 sqrt(q); P = 90 sqrt(q) − 5q − 120; P′ = 45/sqrt(q) − 5 = 0, sqrt(q) = 9, "},{"text":"q = 81","bold":true},{"text":", "},{"text":"p = 90/9 = ₦10","bold":true},{"text":"."}]},{"text":[{"text":"From marginal functions:","bold":true},{"text":" MR = 150 − x, MC = 0.1x^2 − 4x + 110. MR = MC: x^2 − 30x − 400 = 0, (x − 40)(x + 10) = 0, "},{"text":"x = 40","bold":true},{"text":" (P″ = 3 − 0.2x = −5 < 0)."}]},{"text":[{"text":"Minimum cost route:","bold":true},{"text":" C(x) = 4(3,000 − x) + 5 sqrt(810,000 + x^2). C′ = −4 + 5x/sqrt(810,000 + x^2) = 0; 25x^2 = 16(810,000 + x^2); 9x^2 = 12,960,000; "},{"text":"x = 1,200 m","bold":true},{"text":"."}]},{"text":[{"text":"Profit per unit","bold":true},{"text":" = maximum profit ÷ units. P = −x^3/3 + 729x + 2,700: P′ = 729 − x^2 = 0, x = 27, P = 15,822, so ₦586 per unit."}]}]}]},{"number":"4.3","title":"Monopoly, price discrimination and Cournot duopoly","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Monopolist:","bold":true},{"text":" faces the whole demand curve; maximise P = TR − TC with "},{"text":"MR = MC","bold":true},{"text":", then read price from the demand curve."}]},{"text":[{"text":"Price discrimination (two markets, common MC):","bold":true},{"text":" set "},{"text":"MR1 = MC and MR2 = MC","bold":true},{"text":" separately; price higher in the less elastic market."}]},{"text":[{"text":"No discrimination:","bold":true},{"text":" add the two demands in Q form to get total Q in terms of one price P, then MR = MC."}]},{"text":[{"text":"Cournot duopoly:","bold":true},{"text":" each firm maximises its own profit taking the rival's output as given. Set ∂π1/∂q1 = 0 and ∂π2/∂q2 = 0 (reaction functions), solve together."}]},{"text":[{"text":"Shortcut","bold":true},{"text":" for P = a − q1 − q2 with constant MCs c1, c2: q1 = (a − 2c1 + c2)/3; q2 = (a − 2c2 + c1)/3."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Monopoly (P = 70 − 2q, C = 10 + 30q):","bold":true},{"text":" TR = 70q − 2q^2, MR = 70 − 4q, MC = 30. 70 − 4q = 30, "},{"text":"q = 10","bold":true},{"text":"; "},{"text":"P = 70 − 20 = ₦50","bold":tru$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 17, $study_guide$e},{"text":"; TR = 50 × 10 = "},{"text":"₦500","bold":true},{"text":"; TC = 10 + 300 = "},{"text":"₦310","bold":true},{"text":"; profit = "},{"text":"₦190","bold":true},{"text":"."}]},{"text":[{"text":"Two roots of MR = MC:","bold":true},{"text":" R = 1,000Q − 2Q^2, C = Q^3 − 59Q^2 + 1,315Q + 2,000. MR = 1,000 − 4Q; MC = 3Q^2 − 118Q + 1,315. Equate: 3Q^2 − 114Q + 315 = 0, Q^2 − 38Q + 105 = 0, "},{"text":"Q = 3 or 35","bold":true},{"text":". P″ = −4 − (6Q − 118): at 3 it is +96 (minimum profit), at 35 it is −96 (maximum profit)."}]},{"text":[{"text":"Revenue vs profit (P + 2Q = 20, TC = Q^3 − 8Q^2 + 20Q + 2):","bold":true},{"text":" TR = 20Q − 2Q^2 peaks at Q = 5. Profit = −Q^3 + 6Q^2 − 2; P′ = −3Q^2 + 12Q = 0, Q = 4; profit = "},{"text":"30","bold":true},{"text":". MR = 0 always marks maximum TR (P + Q = 100: Q = 50, TR = 2,500)."}]},{"text":[{"text":"Average-cost form (x = 480 − 20p, AC = 10 + x/15):","bold":true},{"text":" p = 24 − x/20; TR = 24x − x^2/20; TC = x·AC = 10x + x^2/15. P′ = 14 − x/10 − 2x/15 = 14 − 7x/30 = 0, "},{"text":"x = 60","bold":true},{"text":", "},{"text":"p = 24 − 3 = ₦21","bold":true},{"text":"."}]},{"text":[{"text":"Price discrimination (P1 = 50 − 5Q1, P2 = 30 − 4Q2, TC = 10 + 10Q):","bold":true},{"text":" MC = 10. MR1 = 50 − 10Q1 = 10, Q1 = 4, "},{"text":"P1 = ₦30","bold":true},{"text":". MR2 = 30 − 8Q2 = 10, Q2 = 2.5, "},{"text":"P2 = ₦20","bold":true},{"text":". Profit = 120 + 50 − (10 + 65) = ₦95."}]},{"text":[{"text":"Same market, no discrimination:","bold":true},{"text":" Q1 = 10 − 0.2P, Q2 = 7.5 − 0.25P; Q = 17.5 − 0.45P, so P = (17.5 − Q)/0.45. MR = (17.5 − 2Q)/0.45 = 10, Q = 6.5; "},{"text":"P = 11/0.45 = ₦24.44","bold":true},{"text":"; profit = (11/0.45) × 6.5 − 75 = "},{"text":"₦83.89","bold":true},{"text":" (2 d.p.), less than ₦95."}]},{"text":[{"text":"Cournot (P = 40 − q1 − q2, TC1 = 6q1, TC2 = 8q2):","bold":true},{"text":" π1 = (40 − q1 − q2)q1 − 6q1; ∂π1/∂q1 = 34 − 2q1 − q2 = 0. π2 = (40 − q1 − q2)q2 − 8q2; ∂π2/∂q2 = 32 − q1 − 2q2 = 0. Solve: "},{"text":"q1 = 12, q2 = 10","bold":true},{"text":"; "},{"text":"P = 40 − 22 = ₦18","bold":true},{"text":"; π1 = (18 − 6)12 = "},{"text":"₦144","bold":true},{"text":"; π2 = (18 − 8)10 = "},{"text":"₦100","bold":true},{"text":"; together "},{"text":"₦244","bold":true},{"text":"; revenue of firm II = 18 × 10 = "},{"text":"₦180","bold":true},{"text":"."}]},{"text":[{"text":"Shortcut check (P = 20 − q1 − q2, c1 = 4, c2 = 6):","bold":true},{"text":" q1 = (20 − 8 + 6)/3 = 6, q2 = (20 − 12 + 4)/3 = 4, P = ₦10, π1 = ₦36, π2 = ₦16."}]}]}]},{"number":"4.4","title":"Functions of two variables and marginal analysis","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Partial derivative f_x (∂f/∂x):","bold":true},{"text":" differentiate in x, treating y as a constant; f_y likewise."}]},{"text":[{"text":"Second order:","bold":true},{"text":" f_xx, f_yy, f_xy = (f_x)_y, f_yx; for ordinary functions "},{"text":"f_xy = f_yx","bold":true},{"text":"."}]},{"text":[{"text":"Marginal product:","bold":true},{"text":" Q_K, Q_L ≈ extra output from one more unit of K or L. "},{"text":"Q_LL < 0","bold":true},{"text":" means diminishing marginal product of labour: with capital fixed, one more worker-hour adds less output when the labour force is large."}]},{"text":[{"text":"Total differential:","bold":true},{"text":" ΔQ ≈ Q_x·Δx + Q_y·Δy. "},{"text":"Percentage change","bold":true},{"text":" ≈ 100·ΔQ/Q."}]},{"text":[{"text":"Power functions:","bold":true},{"text":" if Q = A·K^a·L^b, % change in Q ≈ a(% change in K) + b(% change in L). Cobb-Douglas Q = A·K^α·L^(1−α) has "},{"text":"constant returns","bold":true},{"text":": raise both inputs by 1% and Q rises 1%; double both and Q doubles."}]},{"text":[{"text":"Chain rule:","bold":true},{"text":" if x, y depend on t, dz/dt = z_x·(dx/dt) + z_y·(dy/dt)."}]},{"text":[{"text":"Level curves (f constant):","bold":true},{"text":" dy/dx = −f_x/f_y; to keep output fixed, Δy ≈ −(f_x/f_y)Δx."}]},{"text":[{"text":"Exact change","bold":true},{"text":" = new value − old value (not the derivative estimate)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Evaluate:","bold":true},{"text":" f(x, y) = 3x + y^2: f(2, 3) = 6 + 9 = 15; f(2, sqrt 2) = 6 + 2 = 8. Q = 500x^0.3 y^0.7 at (300, 50) is about 42,794; at (600, 100) it is 85,588 (exactly doubles, since 0.3 + 0.7 = 1)."}]},{"text":[{"text":"Partials:","bold":true},{"text":" f = 4x^2 − 3xy + 5y^2 gives f_x = 8x − 3y, f_y = −3x + 10y. f = 2x^2 + 3x + y^2: dy/dx = −(4x + 3)/(2y). Watch the minus sign: −(−15x^4)/(12y^2 + 6) = +15x^4/(12y^2 + 6)."}]},{"text":[{"text":"Product and chain inside:","bold":true},{"text":" f = x·e^(xy) + y^2. f_x = e^(xy) + xy·e^(xy); at (1, 2) = e^2 + 2e^2 = "},{"text":"3e^2","bold":true},{"text":". f_y = x^2·e^(xy) + 2y; at (1, 2) = "},{"text":"e^2 + 4","bold":true},{"text":"."}]},{"text":[{"text":"Second order:","bold":true},{"text":" f = xy^3 + 5xy^2 + 2x + 1: f_x = y^3 + 5y^2 + 2, "},{"text":"f_xx = 0","bold":true},{"text":", "},{"text":"f_xy = f_yx = 3y^2 + 10y","bold":true},{"text":"; f_y = 3xy^2 + 10xy, "},{"text":"f_yy = 6xy + 10x","bold":true},{"text":". For f = ln(x^2 + 4y): f_x = 2x/(x^2 + 4y); quotient rule gives f_xx = (8y − 2x^2)/(x^2 + 4y)^2; at (2, 1/2): (4 − 8)/36 = "},{"text":"−1/9","bold":true},{"text":"."}]},{"text":[{"text":"Marginal products:","bold":true},{"text":" Q = 2,000x^0.5 y^0.5 at x = 16, y = 144: Q_x = 1,000·sqrt(y/x) = 1,000 × 3 = "},{"text":"3,000","bold":true},{"text":"; Q_y = 1,000·sqrt(x/y) = "},{"text":"333.33","bold":true},{"text":"."}]},{"text":[{"text":"Capital in ₦1,000 units (Q = 60K^(1/2)L^(1/3), K = 900, L = 1,000):","bold":true},{"text":" Q_K = 30K^(−1/2)L^(1/3) = 30 × (1/30) × 10 = "},{"text":"10","bold":true},{"text":" units per extra ₦1,000. Q_L = 20K^(1/2)L^(−2/3) = 20 × 30/100 = 6. Adding ₦1,000 and 2 worker-hours: ΔQ ≈ 10(1) + 6(2) = "},{"text":"22","bold":true},{"text":"."}]},{"text":[{"text":"Percentages:","bold":true},{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 18, $study_guide$:" Q = 600K^(1/2)L^(1/3), labour +2%: (1/3)(2) = "},{"text":"0.67%","bold":true},{"text":". V = πr^2h, r +1%, h +2%: 2(1) + 1(2) = "},{"text":"4%","bold":true},{"text":"."}]},{"text":[{"text":"Total differential:","bold":true},{"text":" Q = 0.08x^2 + 0.12xy + 0.03y^2 at (80, 200): Q_x = 0.16x + 0.12y = 36.8; Q_y = 0.12x + 0.06y = 21.6. ΔQ ≈ 36.8(0.5) + 21.6(2) = "},{"text":"61.6","bold":true},{"text":"."}]},{"text":[{"text":"Chain rule:","bold":true},{"text":" z = x^2 + 3xy, x = 2t + 1, y = t^2. dz/dt = (2x + 3y)(2) + (3x)(2t) = 2(3t^2 + 4t + 2) + 6t(2t + 1) = "},{"text":"18t^2 + 14t + 4","bold":true},{"text":". Demand Q = 300 − 20x^2 + 30y with x = 2 + 0.05t, y = 2 + 0.1 sqrt(t), at t = 4: x = y = 2.2; dQ/dt = (−40x)(0.05) + 30(0.05/sqrt t) = −4.4 + 0.75 = "},{"text":"−3.65","bold":true},{"text":" (decreasing)."}]},{"text":[{"text":"Offsetting change:","bold":true},{"text":" f = 10x·y^(1/2) at (30, 36): f_x = 10 sqrt(y) = 60; f_y = 5x/sqrt(y) = 25. Δy ≈ −(60/25)(1) = "},{"text":"−2.4 hours","bold":true},{"text":". Utility (x + 1)(y + 2) at (25, 8): U_x = 10, U_y = 26; giving up 1 unit of y needs Δx ≈ 26/10 = "},{"text":"2.6 units","bold":true},{"text":"."}]},{"text":[{"text":"Exact vs estimate:","bold":true},{"text":" Q = 10x^2y at (20, 40) = 160,000. Q(21, 40) = 176,400, change "},{"text":"16,400","bold":true},{"text":"; Q(21, 41) = 180,810, change "},{"text":"20,810","bold":true},{"text":"."}]}]}]},{"number":"4.5","title":"Two-variable optimisation and Lagrange multipliers","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unconstrained steps:","bold":true},{"text":" (1) solve f_x = 0 and f_y = 0 together; (2) compute "},{"text":"D = f_xx·f_yy − (f_xy)^2","bold":true},{"text":" at the point."}]}]},{"type":"table","header":[[{"text":"D and f_xx"}],[{"text":"Conclusion"}]],"rows":[[[{"text":"D > 0, f_xx < 0"}],[{"text":"relative maximum"}]],[[{"text":"D > 0, f_xx > 0"}],[{"text":"relative minimum"}]],[[{"text":"D < 0"}],[{"text":"saddle point"}]],[[{"text":"D = 0"}],[{"text":"inconclusive"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Lagrange method","bold":true},{"text":" (optimise f(x, y) subject to g(x, y) = k): form F = f(x, y) − λ[g(x, y) − k]; solve F_x = 0, F_y = 0, F_λ = 0, i.e. "},{"text":"f_x = λg_x, f_y = λg_y, g = k","bold":true},{"text":". Then put x, y into f."}]},{"text":[{"text":"Meaning of λ:","bold":true},{"text":" λ = dM/dk, the approximate change in the optimal value M when the constraint (budget) rises by 1 unit. ΔM ≈ λ·Δk."}]},{"text":[{"text":"Cobb-Douglas shortcut:","bold":true},{"text":" maximise A·x^a·y^b (or a·ln x + b·ln y) subject to p1x + p2y = B: spend a/(a + b) of B on x and b/(a + b) on y."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Minimum (f = x^2 − xy + y^2 − 9x + 5):","bold":true},{"text":" f_x = 2x − y − 9 = 0; f_y = −x + 2y = 0, so x = 2y; 3y = 9, y = 3, x = 6. D = 2·2 − (−1)^2 = 3 > 0, f_xx = 2 > 0: "},{"text":"relative minimum at (6, 3)","bold":true},{"text":", f = 36 − 18 + 9 − 54 + 5 = "},{"text":"−22","bold":true},{"text":". f = x^2 + y^2: D = 4, minimum at (0, 0); f = y^2 − x^2: D = −4, "},{"text":"saddle point","bold":true},{"text":"."}]},{"text":[{"text":"Profit (P = 412x + 806y − x^2 − 4y^2 − xy − 50,000):","bold":true},{"text":" P_x = 412 − 2x − y = 0; P_y = 806 − x − 8y = 0. y = 412 − 2x, so 806 − x − 3,296 + 16x = 0, "},{"text":"x = 166, y = 80","bold":true},{"text":". D = (−2)(−8) − 1 = 15 > 0, maximum. P = 68,392 + 64,480 − 27,556 − 25,600 − 13,280 − 50,000 = "},{"text":"16,436","bold":true},{"text":"."}]},{"text":[{"text":"Two products (umbrellas at ₦20 and ₦25, cost C in ₦ thousands):","bold":true},{"text":" P = 20x + 25y − C. P_x = −6x + 3y − 12 = 0; P_y = 3x − 3y + 54 = 0. Add: −3x + 42 = 0, "},{"text":"x = 14, y = 32","bold":true},{"text":" (14,000 and 32,000). P = 280 + 800 − 370 = 710, i.e. "},{"text":"₦710,000","bold":true},{"text":"."}]},{"text":[{"text":"Two prices:","bold":true},{"text":" P = (x − 30)(70 − 5x + 4y) + (y − 40)(80 + 6x − 7y). P_x = −10x + 10y − 20; P_y = 10x − 14y + 240. Then y = x + 2 and −4x + 212 = 0: "},{"text":"x = ₦53, y = ₦55","bold":true},{"text":". At (50, 52): P_x = 0, P_y = 12, so +₦1 on the second brand adds about ₦12; +₦1 and +₦2 adds 0 + 24 = ₦24."}]},{"text":[{"text":"Separate terms:","bold":true},{"text":" profit = 100[320y/(y + 2) + 160x/(x + 4)] − 1,000(x + y) naira. P_x = 64,000/(x + 4)^2 − 1,000 = 0, (x + 4)^2 = 64, x = 4; P_y = 64,000/(y + 2)^2 − 1,000 = 0, y = 6: "},{"text":"₦4,000 development, ₦6,000 promotion","bold":true},{"text":"."}]},{"text":[{"text":"Lagrange (f = 20x^(3/2)y, x + y = 60, ₦ thousands):","bold":true},{"text":" 30x^(1/2)y = λ and 20x^(3/2) = λ. Equate: 30y = 20x, y = 2x/3; x + 2x/3 = 60, "},{"text":"x = 36, y = 24","bold":true},{"text":" (₦36,000 and ₦24,000). f = 20 × 216 × 24 = "},{"text":"103,680 copies","bold":true},{"text":". λ = 20 × 36^(3/2) = 4,320; budget up by 0.2 thousand: ΔM ≈ 4,320 × 0.2 = "},{"text":"864 copies","bold":true},{"text":"."}]},{"text":[{"text":"Shortcut uses:","bold":true},{"text":" 16L^0.25K^0.75, ₦50 and ₦100, ₦500,000: labour gets 1/4 = ₦125,000, "},{"text":"L = 2,500","bold":true},{"text":"; capital ₦375,000, "},{"text":"K = 3,750","bold":true},{"text":". U = 10x^0.6y^0.4, ₦20 and ₦30, ₦600: "},{"text":"x = 360/20 = 18, y = 240/30 = 8","bold":true},{"text":"; λ = U_x/20 = 0.3(8/18)^0.4 ≈ "},{"text":"0.22","bold":true},{"text":" per extra ₦1. Q = 5 ln X + 6 ln Y, ₦8 and ₦16, ₦352,000: X = (5/11)(352,000)/8 = "},{"text":"20,000","bold":true},{"text":", Y = (6/11)(352,000)/16 = "},{"text":"12,000","bold":true},{"text":", Q = 5 ln 20,000 + 6 ln 12,000 = "},{"text":"105.873","bold":true},{"text":"."}]},{"text":[{"text":"Substitution method:","bold":true},{"text":" max 4x − x^3 + 2y with x + y = 1: y = 1 − x, f = 2 + 2x − x^3; f′ = 2 − 3x^2 = 0, x = sqrt(2/3) = 0.8165, y = 0.1835, f = "},{"text":"3.0887","bold":true},{"text":" (4 d.p.). 10x + 4y − 2x^2 − y^2 with 2x + y$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 19, $study_guide$ = 5: 10 − 4x = 2λ, 4 − 2y = λ give x = y + 1/2; x = 11/6, y = 4/3, maximum "},{"text":"91/6","bold":true},{"text":". xy with x^2 + y^2 = 8: y = 2λx, x = 2λy give x^2 = y^2 = 4; "},{"text":"maximum 4, minimum −4","bold":true},{"text":". 3x^2 + 5xy − 6y^2 + 26x + 12y with 3x + y = 170: 6x + 5y + 26 = 3λ, 5x − 12y + 12 = λ; eliminate λ: 9x = 41y − 10; with the constraint, y = 130/11 = 11.82, x = 580/11 = 52.73, f = "},{"text":"12,130.91","bold":true},{"text":"."}]}]}]},{"number":"4.6","title":"Exponential growth and decay models","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exponential growth:","bold":true},{"text":" Q(t) = Q0·e^(kt), k > 0 (continuous rate); "},{"text":"decay:","bold":true},{"text":" Q(t) = Q0·e^(−kt). Discrete version: Q = Q0(1 + r)^t."}]},{"text":[{"text":"Rate of change:","bold":true},{"text":" dQ/dt = kQ, so the "},{"text":"percentage rate of change","bold":true},{"text":" = 100·Q′/Q = 100k (constant)."}]},{"text":[{"text":"Percentage rate of change","bold":true},{"text":" of any f: 100·f′(t)/f(t)."}]},{"text":[{"text":"Doubling time","bold":true},{"text":" = ln 2/k; "},{"text":"half-life","bold":true},{"text":" = ln 2/k (ln 2 ≈ 0.6931)."}]},{"text":[{"text":"Learning curve:","bold":true},{"text":" Q = B − A·e^(−kt) rises towards the ceiling B; Q′ = kA·e^(−kt) > 0 but falls over time."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Growth:","bold":true},{"text":" a Lagos suburb of 2 million grows at 3% continuously: Q(5) = 2e^(0.15) = "},{"text":"2.324 million","bold":true},{"text":" (3 d.p.). Doubling time = 0.6931/0.03 = "},{"text":"23.1 years","bold":true},{"text":"."}]},{"text":[{"text":"Decay:","bold":true},{"text":" V = 500,000e^(−0.1t) for a ₦500,000 machine: V(5) = 500,000e^(−0.5) = "},{"text":"₦303,265","bold":true},{"text":" (nearest naira); half-life 6.93 years."}]},{"text":[{"text":"Percentage rate:","bold":true},{"text":" GNP N(t) = t^2 + 5t + 106: at t = 10, N′ = 2(10) + 5 = 25, N = 256, rate = 100 × 25/256 = "},{"text":"9.77%","bold":true},{"text":"."}]},{"text":[{"text":"Learning curve:","bold":true},{"text":" Q = 120 − 80e^(−0.2t) units a day after t weeks: Q(5) = 120 − 80e^(−1) = "},{"text":"90.57","bold":true},{"text":" units; output can never pass 120."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stationary point f′ = 0; f″ < 0 maximum, f″ > 0 minimum, f″ = 0 use sign of f′."}]},{"text":[{"text":"Inflection = concavity change; point of diminishing returns = inflection of sales/output."}]},{"text":[{"text":"Min AC: d(AC)/dx = 0, where AC = MC. Max revenue: MR = 0. Max profit: MR = MC with P″ < 0."}]},{"text":[{"text":"Price discrimination: MR in each market = MC. Cournot: solve both reaction functions; q1 = (a − 2c1 + c2)/3."}]},{"text":[{"text":"Partials hold the other variable constant; ΔQ ≈ Q_xΔx + Q_yΔy; dy/dx = −f_x/f_y."}]},{"text":[{"text":"Cobb-Douglas with exponents summing to 1: constant returns."}]},{"text":[{"text":"Two variables: D = f_xx·f_yy − (f_xy)^2; D < 0 saddle."}]},{"text":[{"text":"Lagrange: f_x = λg_x, f_y = λg_y, g = k; λ = change in optimum per unit of budget."}]},{"text":[{"text":"Growth Q0e^(kt): percentage rate 100k, doubling time ln 2/k."}]}]}],"theory":{"itemId":"30170638-cfef-567e-beeb-18d16565546f","question":[{"type":"paragraph","text":[{"text":"Find and classify the stationary point of f(x, y) = 2x^2 + y^2 − 4x + 6y + 15, and give the value of f there."}]}]},"practice":[{"topic":"Optimization and Growth Models","named":false}]}},{"kind":"note","itemId":"6fd6fe39-85d8-59ff-9aba-74e2d13498a4","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Demand, Supply, Cost, Revenue and Break-even","body":"Demand and supply functions and market equilibrium (linear, quadratic, fractional and two-product); excess demand and excess supply; taxes and subsidies; cost functions (FC, VC, AFC, AVC, ATC, MC); revenue, profit and market type; price elasticity of demand; break-even, contribution and margin of safety.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"Demand and supply functions and market equilibrium (linear, quadratic, fractional and two-product); excess demand and excess supply; taxes and subsidies; cost functions (FC, VC, AFC, AVC, ATC, MC); revenue, profit and market type; price elasticity of demand; break-even, contribution and margin of safety."}],"lessons":[{"number":"5.1","title":"Demand, supply and market equilibrium","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand function:","bold":true},{"text":" the amount of a commodity buyers are willing to purchase at various prices. Written x = f(p) or, as an "},{"text":"inverse demand function","bold":true},{"text":", p = g(x). Demand falls as price rises."}]},{"text":[{"text":"Supply function:","bold":true},{"text":" the amount sellers have available to offer at various prices. Supply rises as price rises."}]},{"text":[{"text":"Market equilibrium:","bold":true},{"text":" the point where the demand and supply curves intersect: "},{"text":"Qd = Qs","bold":true},{"text":" (or D(p) = S(p)). No surplus, no shortage. (In set language, equilibrium is the "},{"text":"intersection","bold":true},{"text":" of the demand set and the supply set.)"}]}]},{"type":"paragraph","text":[{"text":"Steps for any equilibrium question:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set demand equal to supply."}]},{"text":[{"text":"Solve for the price (or quantity). Clear fractions first; a quadratic gives two roots."}]},{"text":[{"text":"Reject","bold":true},{"text":" negative prices or quantities."}]},{"text":[{"text":"Substitute back into either function for the other value."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Linear function from two points:","bold":true},{"text":" slope d = (Q2 − Q1)/(P2 − P1); then Q = c + dP passes through one point."}]},{"text":[{"text":"Multi-variable demand:","bold":true},{"text":" Q = a $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 20, $study_guide$− bP + cY + dT + ePr (Y = income, T = taste, Pr = price of a related good). Positive coefficient on Pr: "},{"text":"substitutes","bold":true},{"text":"; negative: "},{"text":"complements","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1 (linear).","italic":true},{"text":" Qd = 60 − 0.8P, Qs = 10 + 0.2P."}]},{"type":"paragraph","text":[{"text":"60 − 0.8P = 10 + 0.2P → 50 = P. Q = 10 + 0.2(50) = "},{"text":"20","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 2 (inverse form, units in thousands).","italic":true},{"text":" A made-in-Nigeria car: demand P = −14q + 740, supply P = 10q − 220 (P in ₦ thousand, q in thousands)."}]},{"type":"paragraph","text":[{"text":"−14q + 740 = 10q − 220 → −24q = −960 → q = 40. P = 10(40) − 220 = 180."}]},{"type":"paragraph","text":[{"text":"So "},{"text":"40,000 cars at ₦180,000","bold":true},{"text":". Trap: the option \"q = 180,000, P = ₦40,000\" swaps them."}]},{"type":"paragraph","text":[{"text":"Example 3 (quadratic).","italic":true},{"text":" S(p) = p^2 + 3p − 70, D(p) = 410 − p."}]},{"type":"paragraph","text":[{"text":"p^2 + 3p − 70 = 410 − p → p^2 + 4p − 480 = 0 → (p + 24)(p − 20) = 0. Reject −24, so "},{"text":"p = ₦20","bold":true},{"text":"; units = 410 − 20 = "},{"text":"390","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Inverse forms work the same way: 90 − 0.1q^2 = 50 + q + 0.2q^2 → 0.3q^2 + q − 40 = 0 → q = [−1 + √(1 + 48)]/0.6 = 10 (thousand chips), p = 90 − 0.1(100) = "},{"text":"₦80","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (fraction).","italic":true},{"text":" S = 3p − 30, D = 600/p."}]},{"type":"paragraph","text":[{"text":"3p − 30 = 600/p → 3p^2 − 30p − 600 = 0 → p^2 − 10p − 200 = 0 → (p − 20)(p + 10) = 0 → "},{"text":"p = ₦20","bold":true},{"text":", D = 600/20 = "},{"text":"30","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"For D = 10p/(p − 3), S = p^2: 10p = p^2(p − 3) → p(p^2 − 3p − 10) = 0 → p = 0, 5 or −2. Only p = 5 (> 3) works: "},{"text":"p = ₦5, quantity 25","bold":true},{"text":". With a cubic such as (5p − 2)/(p − 3) = p^2 + 2, test whole-number prices: p = 4 gives 18/1 = 18 = 16 + 2, so "},{"text":"p = ₦4, quantity 18","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 5 (linear and nonlinear together).","italic":true},{"text":" Demand 2p^2 + q^2 = 11, supply p + 2q = 7. Substitute p = 7 − 2q: 2(7 − 2q)^2 + q^2 = 11 → 9q^2 − 56q + 87 = 0 → q = 3 or 29/9, giving p = 1 or 5/9. Both are positive, so "},{"text":"both","bold":true},{"text":" are equilibria. Likewise (q + 20)(p + 10) = 400 with q = 2p − 7 gives (2p + 13)(p + 10) = 400 → 2p^2 + 33p − 270 = 0 → p = 6 (reject −22.5), "},{"text":"q = 5","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 6 (two competing products).","italic":true},{"text":" qd1 = 100 − 2p1 + 3p2, qs1 = 2p1 − 4; qd2 = 150 + 4p1 − p2, qs2 = 3p2 − 6."}]},{"type":"paragraph","text":[{"text":"Market 1: 4p1 − 3p2 = 104. Market 2: 4p1 − 4p2 = −156. Subtract: p2 = 260; then 4p1 = 104 + 780 → p1 = 221. q1 = 2(221) − 4 = "},{"text":"438","bold":true},{"text":", q2 = 3(260) − 6 = "},{"text":"774","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 7 (find the function or a constant).","italic":true},{"text":" If Qd = 200 − 5P, Qs = a + 3P and equilibrium is at P = 20: Qd = 100, so a + 60 = 100 → "},{"text":"a = 40","bold":true},{"text":". From two points: 100 packs at ₦40, 180 at ₦60: d = 80/20 = 4; 100 = c + 4(40) → c = −60. "},{"text":"Qs = 4P − 60.","bold":true},{"text":" Demand works the same: 1,000 units at ₦4 and 1,500 at ₦2 give slope −250, so x = 2000 − 250p."}]},{"type":"paragraph","text":[{"text":"Example 8 (multi-variable).","italic":true},{"text":" Q = 200 − 4P + 0.01Y + 2T, Y = 30,000, T = 10, Q = 260: 260 = 200 − 4P + 300 + 20 → 4P = 260 → "},{"text":"P = ₦65","bold":true},{"text":". If Q = 800 − 10P + 0.04Y − 2Pr and income rises by ₦5,000, Q rises by 0.04 × 5,000 = "},{"text":"200 units","bold":true},{"text":"."}]}]},{"number":"5.2","title":"Excess demand, excess supply, taxes and subsidies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Excess demand = Qd − Qs","bold":true},{"text":" (a shortage). Occurs when price is "},{"text":"below","bold":true},{"text":" equilibrium; price is bid back up."}]},{"text":[{"text":"Excess supply = Qs − Qd","bold":true},{"text":" (a surplus). Occurs when price is "},{"text":"above","bold":true},{"text":" equilibrium; sellers bid the price down."}]},{"text":[{"text":"Per-unit tax t on producers:","bold":true},{"text":" producers receive (P − t), so replace P by (P − t) in the supply function. In inverse form P = S(Q), the new supply is P = S(Q) + t."}]},{"text":[{"text":"Per-unit subsidy s to producers:","bold":true},{"text":" producers receive (P + s): replace P by (P + s); inverse supply shifts down to P = S(Q) − s."}]},{"text":[{"text":"Tax revenue = t × new Q.","bold":true},{"text":" "},{"text":"Subsidy cost = s × new Q.","bold":true},{"text":" Price producers keep = P − t."}]},{"text":[{"text":"Effect of a tax (normal curves): consumer price "},{"text":"rises by less than the tax","bold":true},{"text":", quantity traded "},{"text":"falls","bold":true},{"text":". A subsidy lowers price and raises quantity."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","italic":true},{"text":" Qd = 60 − 0.8P, Qs = 10 + 0.2P (equilibrium P = 50)."}]},{"type":"paragraph","text":[{"text":"At P = 40: Qd = 28, Qs = 18 → excess demand = 28 − 18 = "},{"text":"10","bold":true},{"text":". At P = 70: Qd = 4, Qs = 24 → excess supply = 24 − 4 = "},{"text":"20","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 2 (inverse form).","italic":true},{"text":" P = −14q + 740, P = 10q − 220 (thousands). At ₦250,000: demand q = (740 − 250)/14 = 35; supply q = (250 + 220)/10 = 47. Excess demand = 35,000 − 47,000 = "},{"text":"−12,00$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 21, $study_guide$0","bold":true},{"text":" (negative, because ₦250,000 is above equilibrium: really a surplus). At ₦350,000: supply q = 57, demand q = 390/14 = 27.86. Excess supply = 57,000 − 27,857 ≈ "},{"text":"29,000","bold":true},{"text":" units (nearest thousand)."}]},{"type":"paragraph","text":[{"text":"Example 3 (tax).","italic":true},{"text":" Qd = 100 − 2P, Qs = 2P − 20; before tax: 100 − 2P = 2P − 20 → P = ₦30, Q = 40. A ₦4 tax: new Qs = 2(P − 4) − 20 = 2P − 28."}]},{"type":"paragraph","text":[{"text":"100 − 2P = 2P − 28 → 4P = 128 → "},{"text":"P = ₦32","bold":true},{"text":". Consumers pay ₦2 more (less than ₦4); producers keep 32 − 4 = ₦28; Q = 100 − 64 = 36; tax revenue = 4 × 36 = "},{"text":"₦144","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (subsidy).","italic":true},{"text":" Fertiliser: Qd = 150 − 3P, Qs = 3P + 30 (P in ₦ thousand); before, P = 20. Subsidy ₦6 thousand: Qs = 3(P + 6) + 30 = 3P + 48. 150 − 3P = 3P + 48 → "},{"text":"P = ₦17 thousand","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Inverse form: P = 90 − 2Q, supply P = 30 + Q becomes P = 24 + Q. 90 − 2Q = 24 + Q → Q = 22; subsidy cost = 6 × 22 = "},{"text":"₦132","bold":true},{"text":"."}]}]},{"number":"5.3","title":"Cost functions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost function:","bold":true},{"text":" C(x) = F + V(x), total cost of producing x units."}]},{"text":[{"text":"Fixed cost (FC):","bold":true},{"text":" costs that do not change with output: rent, insurance, taxes. FC = TC(0), the constant term."}]},{"text":[{"text":"Variable cost (VC):","bold":true},{"text":" depends on output: materials, labour, packaging. VC = TC − FC."}]},{"text":[{"text":"Linear cost:","bold":true},{"text":" C(x) = vx + F (v = variable cost per unit)."}]}]},{"type":"table","header":[[{"text":"Measure"}],[{"text":"Formula"}]],"rows":[[[{"text":"Average fixed cost"}],[{"text":"AFC = FC/Q"}]],[[{"text":"Average variable cost"}],[{"text":"AVC = VC/Q"}]],[[{"text":"Average total cost"}],[{"text":"ATC = TC/Q = AFC + AVC"}]],[[{"text":"Marginal cost"}],[{"text":"MC = d(TC)/dQ"}]],[[{"text":"Total cost from MC"}],[{"text":"TC = ∫ MC dQ + C, with C = FC"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"AVC is "},{"text":"not","bold":true},{"text":" TC/Q. AFC "},{"text":"falls continuously","bold":true},{"text":" as output rises (same fixed cost spread over more units)."}]},{"text":[{"text":"Differentiation rules:","bold":true},{"text":" d/dx (constant) = 0; d/dx (ax) = a; d/dx (x^n) = n·x^(n−1); differentiate a sum term by term."}]},{"text":[{"text":"Cost of the nth unit (exact)","bold":true},{"text":" = C(n) − C(n − 1). MC at (n − 1) approximates it."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","italic":true},{"text":" TC(Q) = 3600 − 177Q − 15Q^2 + 0.5Q^3."}]},{"type":"paragraph","text":[{"text":"FC = TC(0) = "},{"text":"3600","bold":true},{"text":". VC = −177Q − 15Q^2 + 0.5Q^3. AVC = VC/Q = "},{"text":"−177 − 15Q + 0.5Q^2","bold":true},{"text":". AFC = 3600/Q."}]},{"type":"paragraph","text":[{"text":"MC: differentiate each term: 0 − 177 − 15(2Q) + 0.5(3Q^2) = "},{"text":"−177 − 30Q + 1.5Q^2","bold":true},{"text":". Integrating MC and using TC(0) = 3600 rebuilds TC."}]},{"type":"paragraph","text":[{"text":"Example 2 (from totals).","italic":true},{"text":" TC = ₦1,000,000, VC = ₦200,000, output 40,000: FC = 800,000; AFC = 800,000/40,000 = "},{"text":"₦20","bold":true},{"text":". TC ₦450,000 with FC ₦150,000 at 2,500 units: AVC = 300,000/2,500 = "},{"text":"₦120","bold":true},{"text":". AFC ₦25 and AVC ₦75 at 400 units: TC = (25 + 75) × 400 = "},{"text":"₦40,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 3 (build the linear cost).","italic":true},{"text":" 500 items cost ₦40,000 including FC ₦2,000: v = 38,000/500 = "},{"text":"₦76","bold":true},{"text":"; 600 items cost 2,000 + 76(600) = "},{"text":"₦47,600","bold":true},{"text":". If 300 units cost ₦51,000 and 500 cost ₦75,000: v = 24,000/200 = 120; FC = 51,000 − 120(300) = "},{"text":"₦15,000","bold":true},{"text":". A Yaba bakery with FC ₦350,000, v = ₦180 and TC ₦1,070,000 made 720,000/180 = "},{"text":"4,000 loaves","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (substitute).","italic":true},{"text":" C(x) = 10,000 + 30x + 0.02x^2 at x = 200: 10,000 + 6,000 + 800 = "},{"text":"₦16,800","bold":true},{"text":"; average = 16,800/200 = "},{"text":"₦84 per unit","bold":true},{"text":". C(q) = q^3 − 30q^2 + 500q + 200: C(10) = 1000 − 3000 + 5000 + 200 = "},{"text":"₦3,200","bold":true},{"text":"; C(9) = 2,999, so the 10th unit costs 3,200 − 2,999 = "},{"text":"₦201","bold":true},{"text":" (MC(9) = 203 is only the estimate). From C(x) = 2,000 + 15x + 0.1x^2, the rise from 50 to 60 units is 3,260 − 3,000 = "},{"text":"₦260","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 5 (cost over time).","italic":true},{"text":" C(q) = q^2 + q + 900 and q(t) = 25t. After 3 hours q = 75, C = 5,625 + 75 + 900 = "},{"text":"₦6,600","bold":true},{"text":". For C = 11,000: q^2 + q − 10,100 = 0 → q = 100 → t = 100/25 = "},{"text":"4 hours","bold":true},{"text":"."}]}]},{"number":"5.4","title":"Revenue, profit and market type","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Revenue:","bold":true},{"text":" R = (price per unit) × (units sold) = x·p. Always write p in terms of x first (inverse demand), so R is a function of quantity."}]},{"text":[{"text":"Average revenue:","bold":true},{"text":" AR = R/x = p. "},{"text":"Marginal revenue:","bold":true},{"text":" MR = dR/dx."}]},{"text":[{"text":"Profit:","bold":true},{"text":" "},{"text":"P(x) = R(x) − C(x)","bold":true},{"text":" (never C − R)."}]},{"text":[{"text":"Market type:","bold":true},{"text":" AR = MR → "},{"text":"perfectly competitive","bold":true},{"text":"; AR > MR at every Q → "},{"text":"monopolistic","bold":true},{"text":"."}]},{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 22, $study_guide$ext":[{"text":"Revenue maximised","bold":true},{"text":" where MR = 0. "},{"text":"Profit maximised","bold":true},{"text":" where dP/dx = 0 with second derivative negative; for P = ax^2 + bx + c (a < 0) the peak is at x = −b/(2a)."}]},{"text":[{"text":"Several products: R(x, y) = (price A)x + (price B)y. Aspirin at ₦1.25 and ₦1.50: R = 1.25x + 1.50y; for 100 and 150 bottles, 125 + 225 = "},{"text":"₦350","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","italic":true},{"text":" Demand Q = 40 − P. Inverse: P = 40 − Q. TR = (40 − Q)Q = 40Q − Q^2; AR = 40 − Q; MR = "},{"text":"40 − 2Q","bold":true},{"text":". AR > MR, so the firm is "},{"text":"monopolistic","bold":true},{"text":". MR = 0 gives Q = 20 for maximum revenue."}]},{"type":"paragraph","text":[{"text":"Example 2 (make p the subject).","italic":true},{"text":" x = 100 − 4p → p = 25 − x/4 → R = "},{"text":"25x − x^2/4","bold":true},{"text":". x = −5p + 100 → p = 20 − x/5 → R = 20x − x^2/5; at x = 15, R = 300 − 45 = "},{"text":"₦255","bold":true},{"text":". p = 400 − 0.5x at x = 300: p = 250, R = "},{"text":"₦75,000","bold":true},{"text":". If unit price is p = 35x + 15 kobo, R = x(35x + 15) = "},{"text":"35x^2 + 15x","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 3 (profit function).","italic":true},{"text":" C(x) = 500 + 140x, p = 200 − x. R = 200x − x^2. P = 200x − x^2 − 500 − 140x = "},{"text":"−x^2 + 60x − 500","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Coffee makers: p = −0.27x + 51, C = 2.23x^2 + 3.5x + 85. R = −0.27x^2 + 51x; P = "},{"text":"−2.5x^2 + 47.5x − 85","bold":true},{"text":". Profitable where P > 0: roots of x^2 − 19x + 34 = 0 are 2 and 17, so "},{"text":"2 < x < 17","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (price-change model).","italic":true},{"text":" Radios cost ₦2, sell at ₦5, 4,000 bought monthly; each ₦1 rise loses 400 sales."}]},{"type":"paragraph","text":[{"text":"Units at price x: 4000 − 400(x − 5) = 6000 − 400x = "},{"text":"400(15 − x)","bold":true},{"text":". Profit per unit = x − 2. P(x) = "},{"text":"400(15 − x)(x − 2)","bold":true},{"text":" = −400x^2 + 6,800x − 12,000."}]},{"type":"paragraph","text":[{"text":"Maximum: dP/dx = −800x + 6,800 = 0 → "},{"text":"x = ₦8.50","bold":true},{"text":"; P = 400(6.5)(6.5) = "},{"text":"₦16,900","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 5 (profit at a level).","italic":true},{"text":" p = 120 − 2x, C = 300 + 20x, x = 20: R = 80 × 20 = 1,600; C = 700; profit "},{"text":"₦900","bold":true},{"text":". R = 500x − x^2, C = 20,000 + 100x at x = 150: 52,500 − 35,000 = "},{"text":"₦17,500","bold":true},{"text":"."}]}]},{"number":"5.5","title":"Price elasticity of demand","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Elasticity of demand:","bold":true},{"text":" E = −(P/Q)(dQ/dP): the percentage change in quantity demanded caused by a 1% change in price. Percentage form: E = (% change in Q)/(% change in P), in absolute value."}]},{"text":[{"text":"If demand is given as P = f(Q), use dQ/dP = 1 ÷ (dP/dQ)."}]}]},{"type":"table","header":[[{"text":"Coefficient (absolute)"}],[{"text":"Description"}]],"rows":[[[{"text":"0"}],[{"text":"perfectly inelastic"}]],[[{"text":"between 0 and 1"}],[{"text":"relatively inelastic (inelastic)"}]],[[{"text":"1"}],[{"text":"unitary (unit) elastic"}]],[[{"text":"greater than 1"}],[{"text":"relatively elastic (elastic)"}]],[[{"text":"infinity"}],[{"text":"perfectly elastic"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Inelastic:","bold":true},{"text":" a price rise "},{"text":"increases","bold":true},{"text":" total revenue. "},{"text":"Elastic:","bold":true},{"text":" a price rise "},{"text":"decreases","bold":true},{"text":" total revenue. Revenue peaks at unit elasticity."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","italic":true},{"text":" Q = 200 − 4P at P = 20: Q = 120, dQ/dP = −4. E = (20/120)(4) = "},{"text":"0.67","bold":true},{"text":": inelastic."}]},{"type":"paragraph","text":[{"text":"Example 2 (inverse demand).","italic":true},{"text":" P = 60 − 2Q at Q = 10: P = 40, dP/dQ = −2 so dQ/dP = −1/2. E = (40/10)(1/2) = "},{"text":"2","bold":true},{"text":": elastic."}]},{"type":"paragraph","text":[{"text":"Example 3 (at equilibrium).","italic":true},{"text":" Qd = 90 − 3P, Qs = 2P − 10: P = 20, Q = 30. E = (20/30)(3) = "},{"text":"2.00","bold":true},{"text":": elastic."}]},{"type":"paragraph","text":[{"text":"Example 4.","italic":true},{"text":" Garri price rises 10%, quantity falls 4%: E = 4/10 = "},{"text":"0.4","bold":true},{"text":": inelastic, so the seller's revenue rises."}]}]},{"number":"5.6","title":"Break-even analysis","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Break-even point:","bold":true},{"text":" the output at which "},{"text":"total revenue equals total cost","bold":true},{"text":", so profit is zero. Below it, loss; above it, profit. It is a planning tool for new products or ventures."}]},{"text":[{"text":"At break-even: TR = TC; total contribution = FC; profit = 0. (TR = TVC is "},{"text":"not","bold":true},{"text":" a break-even condition.)"}]},{"text":[{"text":"With F = fixed cost, p = price per unit, v = variable cost per unit:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Break-even quantity:","bold":true},{"text":" q = F/(p − v)"}]},{"text":[{"text":"Break-even sales (revenue):","bold":true},{"text":" R = p × q, or F ÷ contribution margin ratio"}]},{"text":[{"text":"Contribution per unit:","bold":true},{"text":" p − v; "},{"text":"total contribution","bold":true},{"text":" = (p − v) × units"}]},{"text":[{"text":"Contribution margin ratio (margin), M:","bold":true},{"text":" (p − v)/p; total cost y = (1 − M)x + F for sales x; break-even sales x = F/M"}]},{"text":[{"text":"Units for a target profit:","bold":true},{"text":" (F + target)/(p$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 23, $study_guide$ − v); "},{"text":"sales for a target profit:","bold":true},{"text":" (F + target)/M"}]},{"text":[{"text":"Price needed to break even at q units:","bold":true},{"text":" p = (F + vq)/q. Example: F ₦50,000, v ₦35, q = 2,000 → p = 120,000/2,000 = ₦60."}]},{"text":[{"text":"Margin of safety:","bold":true},{"text":" actual (or budgeted) sales − break-even sales: how far sales can fall before a loss. As a percentage: ÷ budgeted sales."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Nonlinear break-even:","bold":true},{"text":" set R(x) = C(x) (or P(x) = 0) and solve the quadratic; profit lies "},{"text":"between","bold":true},{"text":" the two roots, loss outside them."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","italic":true},{"text":" Cassettes: F = ₦60,000, v = ₦4, p = ₦7. q = 60,000/3 = "},{"text":"20,000 units","bold":true},{"text":"; sales = 7 × 20,000 = "},{"text":"₦140,000","bold":true},{"text":". At 25,000 units: 7(25,000) − [4(25,000) + 60,000] = "},{"text":"₦15,000","bold":true},{"text":" profit. Keyboards (F ₦10,000, v ₦5, p ₦10): q = "},{"text":"2,000","bold":true},{"text":"; at 1,000 units, 5,000 − 10,000 = a "},{"text":"loss of ₦5,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 2 (target profit).","italic":true},{"text":" p = ₦110, v = ₦60, F = ₦7,500: break-even 7,500/50 = "},{"text":"150 units","bold":true},{"text":"; for ₦1,250 profit, 8,750/50 = "},{"text":"175 units","bold":true},{"text":". If C(x) = 210x + 7000 and price rises from ₦350 to ₦385: 7,000/175 = "},{"text":"40 items","bold":true},{"text":" (was 50)."}]},{"type":"paragraph","text":[{"text":"Example 3 (variable cost as % of revenue).","italic":true},{"text":" p = ₦20, VC = 30% of revenue = ₦6 a unit, F = ₦18,000: P(x) = 20x − 6x − 18,000 = "},{"text":"14x − 18,000","bold":true},{"text":". At p = ₦60 with VC 25%: contribution 45, break-even 18,000/45 = "},{"text":"400 units","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (margin form).","italic":true},{"text":" Gross margin 33% of retail price, other variable costs ₦0.13 per naira of sales, F = ₦4,000. M = 0.33 − 0.13 = 0.20. Break-even sales = 4,000/0.20 = "},{"text":"₦20,000","bold":true},{"text":". At ₦50,000 sales: cost = 0.80(50,000) + 4,000 = 44,000; profit "},{"text":"₦6,000","bold":true},{"text":". Sales ₦40,000, F ₦12,000, M 25%: total cost = 0.75(40,000) + 12,000 = ₦42,000, a "},{"text":"loss of ₦2,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 5 (contribution and safety).","italic":true},{"text":" p = ₦800, v = ₦520: ratio 280/800 = "},{"text":"35%","bold":true},{"text":". F = ₦72,000, p = ₦40, v = ₦22, sales 5,000 units: break-even 72,000/18 = 4,000; margin of safety "},{"text":"1,000 units","bold":true},{"text":". Budgeted ₦500,000, break-even ₦350,000: 150,000/500,000 = "},{"text":"30%","bold":true},{"text":". Ratio 40%, F ₦120,000, target ₦30,000: 150,000/0.40 = "},{"text":"₦375,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 6 (quadratic).","italic":true},{"text":" F = ₦18,000, v = ₦550, p(x) = 4000 − 150x. R = 4000x − 150x^2; C = 18,000 + 550x."}]},{"type":"paragraph","text":[{"text":"4000x − 150x^2 = 18,000 + 550x → 150x^2 − 3450x + 18,000 = 0 → x^2 − 23x + 120 = 0 → (x − 8)(x − 15) = 0 → "},{"text":"x = 8 and x = 15","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"TV sets: 6000x = 50x^2 + 3000x + 43,750 → x^2 − 60x + 875 = 0 → "},{"text":"x = 25 and 35","bold":true},{"text":". With R = 5000x − 100x^2 and C = 35,000 + 500x the roots are 10 and 35, so a loss occurs for "},{"text":"0 ≤ x < 10 or x > 35","bold":true},{"text":"."}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Equilibrium: Qd = Qs; reject negative roots; substitute back."}]},{"text":[{"text":"Excess demand = Qd − Qs (price below equilibrium); excess supply = Qs − Qd (price above)."}]},{"text":[{"text":"Tax t: replace P by (P − t) in supply; revenue = t × new Q; consumers bear less than the full tax."}]},{"text":[{"text":"FC = TC(0); VC = TC − FC; AFC = FC/Q; AVC = VC/Q; ATC = AFC + AVC; MC = dTC/dQ."}]},{"text":[{"text":"R = xp with p in terms of x; P = R − C; AR > MR means monopoly."}]},{"text":[{"text":"E = −(P/Q)(dQ/dP); between 0 and 1 inelastic, above 1 elastic."}]},{"text":[{"text":"Break-even q = F/(p − v); sales = F/M; margin of safety = actual − break-even."}]},{"text":[{"text":"Quadratic break-even: profit between the two roots."}]}]}],"theory":{"itemId":"76ac660f-1f2c-50b9-af24-01aed5ad3cc2","question":[{"type":"paragraph","text":[{"text":"A Lagos print shop makes branded T-shirts with fixed costs of ₦240,000, variable cost ₦900 per shirt and price ₦1,500. Find the break-even quantity, the break-even revenue and the profit on 500 shirts."}]}]},"practice":[{"topic":"Demand, Supply, Cost, Revenue and Break-even","named":false}]}},{"kind":"note","itemId":"c39b3d9d-f328-5e57-91c3-5582cafef42f","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Mathematics of Finance","body":"Percentage change, profit and loss, discounts and depreciation; simple interest, exact and ordinary time, bank discount and stock yield; compound, effective and continuous interest, and solving for time or rate with logarithms; present value, net present value and bonds; annuities, sinking funds and perpetuities; present value of an annuity and amortisation of loans.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"Percentage change, profit and loss, discounts and depreciation; simple interest, exact and ordinary time, bank discount and stock yield; compound, effective and continuous interest, and solving for time or rate with logarithms; present value, net present value and bonds; annuities, sinking funds and perpetuities; present value of an annuity and amortisation of loans."}],"lessons":[{"number":"6.1","title":"Percentages, profit and loss, depreciation","mustKnow":[{"type":"list",$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 24, $study_guide$"ordered":false,"items":[{"text":[{"text":"Multiplier rule:","bold":true},{"text":" a rise of r% multiplies by (1 + r/100); a fall of r% multiplies by (1 − r/100). Successive changes multiply, they never add."}]},{"text":[{"text":"Percentage change","bold":true},{"text":" = (new − old)/old × 100."}]},{"text":[{"text":"Profit %","bold":true},{"text":" = profit/cost price × 100. "},{"text":"Cost price","bold":true},{"text":" after a loss of r%: CP = SP/(1 − r/100); after a gain: CP = SP/(1 + r/100)."}]},{"text":[{"text":"Straight-line (linear) depreciation:","bold":true},{"text":" annual charge = (cost − scrap value)/useful life; value after t years V(t) = cost − (annual charge) × t. The same naira amount is written off every year."}]},{"text":[{"text":"Reducing-balance depreciation:","bold":true},{"text":" V = C(1 − r)^n, r = annual rate as a decimal. The same "},{"text":"percentage of the previous year's value","bold":true},{"text":" is written off each year, so the naira charge falls every year and the value never reaches zero. The yearly values form a geometric progression with common ratio (1 − r)."}]},{"text":[{"text":"Time to fall to a fraction k:","bold":true},{"text":" n = ln k / ln(1 − r). Rate from two values: r = 1 − (V/C)^(1/n)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Successive changes.","bold":true},{"text":" Gold falls 34% then rises 12%: 0.66 × 1.12 = 0.7392, so the overall change is 0.7392 − 1 = −0.2608, a "},{"text":"decrease of about 26%","bold":true},{"text":". A 25% rise then 20% fall: 1.25 × 0.8 = 1, "},{"text":"no overall change","bold":true},{"text":". A 40% fall then 50% rise: 0.6 × 1.5 = 0.9, a "},{"text":"decrease of 10%","bold":true},{"text":". Discounts of 20% then 10%: 0.8 × 0.9 = 0.72, a "},{"text":"single discount of 28%","bold":true},{"text":" (not 30%). After a 20% fall, the price must rise 20/80 × 100 = "},{"text":"25%","bold":true},{"text":" to recover."}]},{"text":[{"text":"Single changes.","bold":true},{"text":" ₦2,500 to ₦3,375: 875/2,500 × 100 = 35%. Sale price after 20% off ₦580: 580 × 0.8 = ₦464. 15% tax on ₦1,360: 1,360 × 1.15 = ₦1,564. A 7% fall on ₦9,500: 9,500 × 0.93 = ₦8,835."}]},{"text":[{"text":"Profit and loss.","bold":true},{"text":" 50 crates at ₦4,800 cost ₦240,000; 45 sold at ₦6,000 bring ₦270,000; profit ₦30,000 = 30,000/240,000 × 100 = "},{"text":"12.5%","bold":true},{"text":". Sold at ₦171,000 at a 5% loss: CP = 171,000/0.95 = "},{"text":"₦180,000","bold":true},{"text":". Tunde buys at ₦6,000; two profits of x% make Musa pay 6,000 + 2,640 = ₦8,640, so 6,000(1 + x/100)^2 = 8,640, (1 + x/100)^2 = 1.44, 1 + x/100 = 1.2, "},{"text":"x = 20","bold":true},{"text":"."}]},{"text":[{"text":"Straight line.","bold":true},{"text":" Machine ₦2,400,000, scrap ₦400,000, 8 years: (2,400,000 − 400,000)/8 = "},{"text":"₦250,000","bold":true},{"text":" a year. Generator ₦1,800,000 to ₦300,000 over 5 years: charge ₦300,000; book value after 3 years = 1,800,000 − 3 × 300,000 = "},{"text":"₦900,000","bold":true},{"text":". Books worth ₦1,500 depreciated linearly to zero over 10 years lose ₦150 a year: "},{"text":"V(t) = 1,500 − 150t","bold":true},{"text":"."}]},{"text":[{"text":"Reducing balance.","bold":true},{"text":" Flat ₦1,500,000 at 25%: 1,500,000 × 0.75^5 = 1,500,000 × 0.2373047 = "},{"text":"₦355,957","bold":true},{"text":". Machine ₦50,000 at 10% for 7 years: 50,000 × 0.9^7 = "},{"text":"₦23,915","bold":true},{"text":". Van ₦3,000,000 at 20% for 4 years: 3,000,000 × 0.8^4 = "},{"text":"₦1,228,800","bold":true},{"text":". Car ₦8,000,000 to ₦4,096,000 in 3 years: (4,096,000/8,000,000)^(1/3) = 0.512^(1/3) = 0.8, so r = "},{"text":"20%","bold":true},{"text":"."}]},{"text":[{"text":"Time to halve.","bold":true},{"text":" At 15%: n = ln 0.5/ln 0.85 = −0.693147/−0.162519 = "},{"text":"4.27 years","bold":true},{"text":". At 7%: n = ln 0.5/ln 0.93 = 9.55; after 9 years the value is still above half (0.93^9 = 0.520), after 10 years it is below (0.484), so to the nearest whole year the answer is "},{"text":"10","bold":true},{"text":"."}]}]}]},{"number":"6.2","title":"Simple interest, bank discount and stock yield","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Simple interest:","bold":true},{"text":" interest on the original principal only, never on interest. I = Pin; F = P + I = P(1 + in)."}]},{"text":[{"text":"P = principal, i = annual rate (decimal), n = time "},{"text":"in years","bold":true},{"text":", F = future value (amount)."}]},{"text":[{"text":"Rearranged: P = I/(in); i = I/(Pn); n = I/(Pi). Months: n = months/12."}]},{"text":[{"text":"Days, 2 methods:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Exact","bold":true},{"text":" method: n = days/365."}]},{"text":[{"text":"Ordinary","bold":true},{"text":" method ("},{"text":"Banker's Rule","bold":true},{"text":"): n = days/360 (twelve 30-day months). Ordinary interest is always the larger."}]}]}]},{"text":[{"text":"Yield on stock","bold":true},{"text":" = annual dividend per share / price per share × 100%."}]},{"text":[{"text":"Bank discount:","bold":true},{"text":" interest worked on the amount repaid (maturity value F), deducted in advance. The borrower receives the "},{"text":"proceeds","bold":true},{"text":" P = F(1 − dn); to receive P now, repay F = P/(1 − dn). d = bank discount rate."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"₦480 at 6¼% for 9 months: I = 480 × 0.0625 × 9/12 = "},{"text":"₦22.50","bold":true},{"text":". Future value for 1 year 6 months: F = 480(1 + 0.0625 × 1.5) = 480 × 1.09375 = "},{"text":"₦525","bold":true},{"text":". ₦5,480 at 9¼% for 9 months: 5,480 × 0.0925 × 0.75 = "},{"text":"₦380.18","bold":true},{"text":" (rounded)."}]},{"text":[{"text":"₦85,000 at 12% for 3 years: I = 85,000 × 0.12 × 3 = "},{"text":"₦30,600","bold":true},{"text":". ₦1,000 at 10% for 5 years: F = 1,000(1 + 0.5) = "},{"text":"₦1,500","bold":true},{"text":".$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_acs213', 25, $study_guide$ ₦20,000 at 6% for 3 months: 20,000(1 + 0.06 × 0.25) = "},{"text":"₦20,300","bold":true},{"text":". ₦5,000 at 10% for 9 months: 5,000 × 1.075 = "},{"text":"₦5,375","bold":true},{"text":"."}]},{"text":[{"text":"Rate:","bold":true},{"text":" ₦1,000 earns ₦45 in 6 months: i = 45/(1,000 × 0.5) = 0.09 = "},{"text":"9%","bold":true},{"text":". ₦5,250 earns ₦55 in 6 months: 55/2,625 = "},{"text":"2.10%","bold":true},{"text":". ₦120,000 becomes ₦159,600 in 3 years: 39,600/(120,000 × 3) = "},{"text":"11%","bold":true},{"text":". Pawnshop ₦50, repaid ₦53.50 a month later: 3.50/(50 × 1/12) = 0.84 = "},{"text":"84%","bold":true},{"text":". To double in 8 years, I = P, so i = 1/8 = "},{"text":"12.5%","bold":true},{"text":"."}]},{"text":[{"text":"Principal:","bold":true},{"text":" ₦18,900 in 2 years 6 months at 14%: P = 18,900/(0.14 × 2.5) = "},{"text":"₦54,000","bold":true},{"text":"."}]},{"text":[{"text":"Time:","bold":true},{"text":" ₦500 to ₦530 at 8%: n = 30/(500 × 0.08) = 0.75 year = "},{"text":"9 months","bold":true},{"text":". ₦40,000 to ₦55,000 at 7.5%: 15,000/3,000 = "},{"text":"5 years","bold":true},{"text":". ₦5,350 to ₦10,165 at 12%: 4,815/642 = "},{"text":"7.50 years","bold":true},{"text":"."}]},{"text":[{"text":"Exact versus ordinary:","bold":true},{"text":" ₦1,460 for 72 days at 10%: exact = 1,460 × 0.1 × 72/365 = "},{"text":"₦28.80","bold":true},{"text":"; ordinary = 1,460 × 0.1 × 72/360 = "},{"text":"₦29.20","bold":true},{"text":". ₦2,190 for 75 days at 12%: exact "},{"text":"₦54.00","bold":true},{"text":", ordinary "},{"text":"₦54.75","bold":true},{"text":". Trap: options swap the two."}]},{"text":[{"text":"Yield:","bold":true},{"text":" dividend ₦3.50, share price ₦87.50: 3.50/87.50 × 100 = "},{"text":"4%","bold":true},{"text":"."}]},{"text":[{"text":"Bank discount:","bold":true},{"text":" promise to pay ₦5,000 in 10 months at d = 8.4%: P = 5,000(1 − 0.084 × 10/12) = 5,000 × 0.93 = "},{"text":"₦4,650","bold":true},{"text":". To receive ₦5,000 now: F = 5,000/0.93 = "},{"text":"₦5,376.34","bold":true},{"text":". ₦15,000 in 5 years at 10%: P = 15,000(1 − 0.5) = "},{"text":"₦7,500","bold":true},{"text":"; to receive ₦15,000 now: F = 15,000/0.5 = "},{"text":"₦30,000","bold":true},{"text":"."}]},{"text":[{"text":"Simple versus compound:","bold":true},{"text":" ₦200,000 at 10% for 3 years. Simple: 200,000 × 0.1 × 3 = ₦60,000. Compound: 200,000 × 1.1^3 − 200,000 = 266,200 − 200,000 = ₦66,200. Difference "},{"text":"₦6,200","bold":true},{"text":"."}]}]}]},{"number":"6.3","title":"Compound, effective and continuous interest","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Compound interest:","bold":true},{"text":" interest is added to the principal at the end of each period, so later interest is earned on principal "},{"text":"plus","bold":true},{"text":" interest already added (\"interest on interest\")."}]},{"text":[{"text":"Period (conversion period):","bold":true},{"text":" the interval at the end of which interest is added to the principal. At the same nominal rate, "},{"text":"the shorter the period, the greater the interest","bold":true},{"text":"."}]},{"text":[{"text":"F = P(1 + i)^n, i = rate per period, n = number of periods. With nominal annual rate r compounded m times a year for t years: "},{"text":"A = P(1 + r/m)^(mt)","bold":true},{"text":". Here m (often written n) is "},{"text":"the number of times interest is compounded per year","bold":true},{"text":": annually 1, semi-annually 2, quarterly 4, monthly 12, weekly 52, daily 365."}]},{"text":[{"text":"Time:","bold":true},{"text":" n = ln(F/P)/ln(1 + i) periods. Doubling, annual compounding: "},{"text":"t = ln 2/ln(1 + r)","bold":true},{"text":"."}]},{"text":[{"text":"Rate:","bold":true},{"text":" i = (F/P)^(1/n) − 1 per period; nominal = m × i."}]},{"text":[{"text":"Effective rate:","bold":true},{"text":" re = (1 + i)^m − 1, the equivalent once-a-year rate; used to compare offers. Nominal from effective: r = m[(1 + re)^(1/m) − 1]."}]},{"text":[{"text":"Continuous compounding:","bold":true},{"text":" "},{"text":"A = Pe^(rt)","bold":true},{"text":" (the limit as m tends to infinity). Effective rate = e^r − 1. Rate: r = ln(A/P)/t. Time: t = ln(A/P)/r."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"₦5,000 at 6% for 10 years","bold":true},{"text":" (one bank set; learn the order):"}],"blocks":[{"type":"table","header":[[{"text":"Compounding"}],[{"text":"Working"}],[{"text":"Amount"}]],"rows":[[[{"text":"Annually"}],[{"text":"5,000(1.06)^10 = 5,000 × 1.790848"}],[{"text":"₦8,954.24"}]],[[{"text":"Semi-annually"}],[{"text":"5,000(1.03)^20"}],[{"text":"₦9,030.56"}]],[[{"text":"Quarterly"}],[{"text":"5,000(1.015)^40"}],[{"text":"₦9,070.09"}]],[[{"text":"Monthly"}],[{"text":"5,000(1.005)^120"}],[{"text":"₦9,096.98"}]],[[{"text":"Daily"}],[{"text":"5,000(1 + 0.06/365)^3650"}],[{"text":"₦9,110.14"}]],[[{"text":"Continuously"}],[{"text":"5,000e^0.6"}],[{"text":"₦9,110.59"}]]]},{"type":"paragraph","text":[{"text":"More frequent compounding gives more, but the gain shrinks; daily is very close to continuous."}]}]},{"text":[{"text":"More amounts (2 d.p.):","bold":true},{"text":" ₦1,000 at 7% annually, 10 years: "},{"text":"₦1,967.15","bold":true},{"text":". ₦500 at 6%, 30 years: "},{"text":"₦2,871.75","bold":true},{"text":". ₦1,000 at 8% per period for 25 periods: 1,000(1.08)^25 = "},{"text":"₦6,848.48","bold":true},{"text":". ₦800 at 6% semi-annually, 5 years: 800(1.03)^10 = "},{"text":"₦1,075.13","bold":true},{"text":". ₦2,500 at 2% monthly, 20 years: "},{"text":"₦3,728.32","bold":true},{"text":". ₦500 at 8% quarterly, 10 years: "},{"text":"₦1,104.02","bold":true},{"text":". ₦10,000 at 12% monthly for 3 years 4 months (40 months): 10,000(1.01)^40 = "},{"text":"₦14,888.64","bold":true},{"text":". ₦5,000 at 9% monthly, 10 years: "},{"text":"₦12,256.79","bold":true},{"text":". ₦80,000 at 9% semi-annually, 3 years: 80,000(1.045)^6 = "},{"text":"₦104,180.81","bold":true},{"text":". ₦250,000$study_guide$);
